window.__D("text/imrei-bina/c006",{"p":[[1700400416,"ומעלימי' האור הבולט הזה שבא מלמעלה וכמו אותיות שקועי' שחלולים שמעלימים לאורות הבולטים שנכנס לתוכן והרי גם אורות עליונים הבאים בבחי' בולט נתעלמו עכ\"פ בכלים מכלים שונים שהוא בחי' יש ודבר מה (כמו אור אהב' פשוטה שבולט בלי כלי ולבוש כנל וכשבאה בבחי' לבוש וכלי נראית ליש ודבר כמו ברוב טובה וחסד בפ\"מ בכלים מגבילי' כו' ניכרת אור האהבה בבחי' יש יותר משא\"כ בהיותה אור פשוט בלי כלי מגבילה כו') (ולפ\"ז מה שמלמטה למעלה הרצוא הבולט נק' יש זהו ברוח העליון הנמשך מלמעלה בחי' אין היפך היש רק כשהאור העליון הנמשך מלמעלה בא בכלי נק' יש כערך בחי' ישות הרוח העולה כו' וד\"ל) וזהו כחותם על זרועך בבחי' שקיעה שהן בחי' כלים מגבילים לאור אהבה שנמשך מלמעלה בבחי' בולט שנעשה מבליטה דלמטה כנ\"ל ומעתה יש להבין ענין ובחי' מדרגה הב' בעבודת ה' מלמטה למעלה ג\"כ הוא בחי' שוב דהיינו בחי' הבטול שהוא ענין השקיעה דלמט' בהיות ידוע שיש ב' מיני התפעלות בתפלה א' האהבה בהתפעל' דבר מה שמצד השגה שיש מי שמשיג ואוהב כו' והב' התפעלות הבטול שהוא ההיפוך מזה והוא שנעשה בטל כאבן דומם בהעדר הרגשת עצמו בשום דבר התפעלות לא בשכל ולא בלב מפני שניזוז ממקומו לגמרי כמו מלך ושר שבא אליו פתאום שמתבטל ממציאותו ונעשה בהעדר ההתפשטות והעדר הרגשת עצמו לגמרי מכל וכל הוא הנק' בטול במציאות כידוע שהוא בטול שלמעלה מן הטעם שזהו בטול דחכמה שלמעלה מבטול דהשגה כו' וכידוע בענין דחילו ורחימו כו' יראה עילאה בושת כו' בהעדר צמצום עצמו שלמעלה גם מאהבה עלא' דכתי' הן ירא' ה' היא חכמ' שירא' זו הנק' בטול במציאו' היא חכמ' שבבחי' ראי' כו' ואהבה עילא' שמתאחדת ממש בהשגה דבינה ונק' בינה בן י\"ה למטה הרבה מאור יראה עלא' זו לפי שאהבה עלא' שהוא מתאחד בה\"א דהשגה באה בבחי' התפשטו' אורך ורוחב היפוך היו\"ד דחכמ' שהוא בבחי' העדר ההתפשטו' כידוע ורחימו הב' שנולדה מן השכל יש גמור הוא במהו' התפעלו' בדבר מה כו' ומכ\"ש יראה חיצוניות עול מ\"ש ה\"א תתאה (ובאמת מאחר שבחי' שוב קאי על הנשמ' ונר ה' נשמת אדם כלולה מד' אותיו' הוי' הרי ודאי כל הד' בחי' הכל בבחי' בטול ושקיעה כיו\"ד דחכמ' כי גם בטול דהשגה נק' שקיעה עכ\"פ וגם האהבה הנולד במורגש בטול רצון יש בו כנ\"ל בפי' ואהבת אבה וכן גם בירא' תתא' עמ\"ש לבטל רצונו שפ\"מ כמאמ' בטל רצונך כו' שכל זה בבחי' שקיעה ובטול העצמו' רק שיו\"ד בטול פנימי יותר] והנה מבואר למעה דרוח אייתי ואמשיך אוח מלמעלה כמוהו ממש דוקא וכך יובן ברוח העולה מלמטה הכל בבחי' שקיעה שהוא בטול העצמות והעדר התפשטות (ברצון ושכל ומדות כו' שכולל שם הוי') כל יומשך רוח העליון מלמעלה למטה ג\"כ בבחי' ואופן זה ממש דהיינו לא שנמשך בבחי' גלוי והתפשטות אור שהוא בחי' יש ודבר מה אלא נמשך מבחי' העצמות שבאא\"ס שאינו מתיישב בכלי ויש כלל מאחר שרוח העולה לא היה בבחי' יש ודבר מה אדרבה בבחי' בטול העצם כנ\"ל כך אייתי ואמשיך רוח והיינו שנמשך עי\"ז בחי' אור העצמות שהוא בא מבחי' צמצום העצמות והעדר התפשטותו למטה למקבלים והוא מבחי' צמצום הראשון שלפני ההשתלשלות שבא בהתפשטות כו' ואע\"פ שזהו נק' צמצום עצמו אין זה כמו שקיעה דלמטה דדוקא מלמטה למעלה נק' שקיעה אבל מלמעלה למטה נהפוך הוא שזה האור הבא מן הצמצום בעצמו כאשר יבא למטה נק' אור בולט דהיינו שנמשך האור העצם כמו שהוא בלי כלי שהוא בחי' ההתפשטו' הנק' יש שמעלים ומלביש האור העצם אלא אדרבה מגלה כל עיקר האור כמו שהוא בעצם תקפו והוא הנק' בחי' בליטה אור שאיננו בא בבחי' כלי ולבוש מעלים כלל כנ\"ל וזהו הבליטה דלמעלה שנעשה משקיעה דלמטה היפך בחי' שקיעה דלמעל' שהן כלים לאורות שנעשה מבליטה שהוא בחי' הרצוא דלמטה כנ\"ל משא\"כ משוב דלמט' נמשך אור העליון כמו שהוא בלי"],[1700400417,"כלי כלל וד\"ל (ועדיין אין זה מתיישב דאם רוח אייתי רוח כמוהו ממש כנ\"ל א\"כ כמו רוח התחתון בבחי' שקיעה בעצמו וכמו דיוקני אשתאר חקוק בך שחקיקה זו בבחי' שקיעה וכמו גליף גליפו וחקיקה בטה\"ע וכמכתב אלקי' חרות על הלוחות שזהו בחי' חק תוכו' כו' וכך באמת מכל בחי' שקיע' דלמט' הי' צריך להיו' בחי' שקיעה למעל' ולא להיפך שנמשך בחי' בולט ומה שדומה כמו השקיעה דלמט' מצד שאיננו מוגבל ובא בכלי ולבוש מעלים הנה ודאי זה לא נק' שוקע בעצם מה שבא בשקיעת וחללה דכלי אדרבה בולט יקרא וכידוע וכן ענין הנ\"ל בבחי' רצוא דלמטה שנעשה שוקע למעלה במה שבא האור בכלי גם זה לכאור' אינו מתיישב לנכון דאם רוח אייתי רוח כמוהו ממש ראוי שיומשך אור בולט כמו שהוא בלא כלי שקוע המגבילו כרוח התחתון כו' אלא שרש הדברי' הללו כלי שקוע המגבילו כרוח התחתון כו' אלא שרש הדברי' הללו כמשי\"ת בסמוך):\n(לב) <b>וביאור</b> הדברי' הנה לע\"ל כתיב ולא יכנף עוד מוריך כו' שלא יהי' גלוי אלקו' עוד בבחי' לבוש וכלי מעלים כלל דהנה עכשיו כל המצות מעשיות הן כלים לאורות העליוני' כמו רמ\"ח פקודי' רמ\"ח אברי' להלביש ולהעלים עצם האור וסיבת זה הדבר ידוע לפי שמה שנמשך האור באצי' ע\"י המצוה ה\"ז בא ע\"י אתדל\"ת שעושה אתדל\"ע וזהו כפי אופן אתדל\"ת כך יהיה אתדל\"ע דרוח אייתי רוח כו' וכמו שבאתדל\"ת מלמטה למעלה נתעורר בבחי' יש ודבר מה כך באופן אותו הדבר נמשך אתדל\"ע מלמעלה למטה בבחי' יש שזהו או\"כ למעלה ודוגמא לדבר מצות הצדקה למטה הוא להחיות רוח שפלים בפשוט לעני ונדכא דלית ליה כלום יתעורר מזה אתדל\"ע באותו אופן ממש שזהו ענין להחיות רוח שפלים למעלה דהיינו מדת הרחמים למעלה באצי' להחיות מאין ליש מאצי' לבריא' בבחי' חסד עליון זה שנמשך מצד אתדל\"ת בא בהתלבשות בכלים מכלים שונים בבי\"ע ממדרגה למדרגה מרוחניות לגשמיות עד שהוא זן ומפרנס כל הברואים בחסד גשמי ושרש הראשון הוא חסד עליון דאצי' ונמשך תחלה מאצי' לבריאה כמו בג\"ע העליון להנות מזיו כו' לנשמות דבריאה ויורד ומשתלשל מעילה לעילה בכל עולם בכלים מכלים שונים עד חסד דמל' דעשיה לזון העולם בגשמיות כו' וכל זה אינו רק בחי' העלמו' ולבושי' לאור העצ' דחס' דאצי' כמו שהו' באצי' ותקונ' דדרוע' כמשל היד שמקביל החסד שבלב הוא הכלי הראשון בבחי' האצי' ומש' יורד ומשתלשל כו' וכך בכל המצות כמקיפים דסוכה שנתלבש אור מקיף העליון דאימא בסכך כענין ופרוס עלינו סוכת שלומך וכה\"ג במקיף דטלית מקיף לחכמה כנ\"ל בפ' ציצית שכל זה בחי' התלבשות בכלים המסתירים לעצם האור כו' וכה\"ג בכל רמ\"ח מ\"ע הן רמ\"ח כלי' שנעשו באתדל\"ת לעורר אתדל\"ע באצי' להיו' או\"כ בזה האופן ממש כו' וכל זה שבא האורו' בכלים ע\"י בחי' הכלים דמ\"ע למטה זהו ע\"י בחי' אהבה בחי' רצוא הנ\"ל כידוע דאהבה שרש כל רמ\"ח מ\"ע שהן ה\"ח כו' אבל הנה בחי' השוב בחי' בטול במציאות הנ\"ל ששרשו למעלה מעורר אתדל\"ע בבחי' המשכת אור העצמו' כמו שהוא שלמעלה מהיות הגבלה בכלי ולבוש הנה זהו מ\"ש ל\"ל ולא יכנף עוד מוריך שלא יתלבש בלבוש וכלי כמצות מעשיו' אלא עיניך רואות כמו שהו' וכמו וא' הנה אלקינו זה ממש כו' והיינו רק מצד שהי' אתדל\"ת בבחי' בטול היש שהוא העדר הכלי הנק' בטול במציאו' ברצון ושכל ומדו' כו' כנ\"ל (ומעין ודוגמא זו דלע\"ל יש גם עכשיו במצות ל\"ת דלאו קודם להן כנ\"ל כידוע דשרש הל\"ת בי\"ה שלמעלה ממ\"ע שהן בו\"ה כי הלאו דל\"ת אינו ענין המשכה בדבר מה כמו במ\"ע הן כו' אלא רק העדר הכלי שלא יעשה כלי לדבר שנגד הרצון כמו לא תאכל חלב ולא תלבש שעטנז וכה\"ג שזהו רק למנוע השפע והמשכה בכלי"],[1700400418,"יהי' שב ואל תעשה בהעדר התפשטו' וכמ\"ש במ\"א שזהו בארץ לא זרועה כו' וד\"ל) ובכל זה יובן מה שאנו או' בש\"ע וזוכר חסדי אבות כו' למען שמו באהבה דוקא דהנה מבואר למעלה בבחי' אהבה דכנ\"י מלמטה למעלה בבחי' רצוא שמעורר כמ\"כ מלמעלה למטה בחי' אהבה עליונה דאצי' מלמעלה למטה כמו אה\"ע אהבתנו כו' דרוח אייתי ואמשיך רוח כמוהו ממש כו' וזהו ואהבת ב\"פ אור גי' ואהבת שזהו בחי' או\"י ואו\"ח בחי' הרצוא מלמט' למעל' או\"ח ואור אה\"ע מלמעלה למטה נק' או\"י (ובענין נעוץ תחלתן בסופן וסופן כו' מבואר בפרד\"ס המשל מהליכת מים ממעיין הנובע בהר לבקעה שחוזר ועולה למקום מקור המעיין ולא הגבה למעלה הימנו ולפ\"ז או\"י קודם לאו\"ח ובאמת כן הוא והוא ברכת אה\"ע אהבתנו כו' עד החתימ' הבוחר בעמו ישראל באהבה שזהו בחי' אהב' עליונה שנמשך מלמעלה למטה בבחי' או\"י דוק' ואח\"כ בק\"ש ואהבת ב\"פ אור או\"י ואו\"ח יחד שאו\"ח דאהבת כנ\"י עולה למקור חוצבו בתחלה דנעוץ סופן כו' והיו לאחדים ממש והוא הנק' היכל אהבה והוא באהבה שסיים בברכת אה\"ע כו' והכיל אהבה דואהבת הכל א' שמכח א' באו ועד\"ז יובן ענין היכל הרצון שבאמת ויציב והיכל ק\"ק דגאולה לתפלה כמשי\"ת) והנה ענין אמת ויציב הוא בחי' היכל הרצון שהוא בחי' אתדבקות רוחא ברוחא כידוע והענין הוא דזהו באה\"ר שבנקודת הרצון שלמעלה מן השכל והתבוננו' וזהו ענין נשיקין דוישק יעקב לרחל שאה\"ר שבלתי מתיישב במוח ולב יוצא בהבל נשיקין כאב שנושק לבנו מרוב אה\"ר שלא יכיל בלבו כו' והיינו מצד בחי' התקשרות עצמיו' דנשמות באלקות כמו כל הנשמה תהלל כו' ונק' קטרת קשורא דנשמתון ורוחין מצד עצם מהותן שלזה א\"צ ציווי ואהבת ביגיע' ע\"י התבוננות אלא ממילא ומאליה כו' ולכך ענין אמת ויציב הוא לאמת את אמת הראשון שבואהבת כמו יציבא מלתא כו' שנקודת התקשרות עצמות ברצון פשוט הוא המאמת לאמת דע\"י השגה וזהו ומתוקן ומקובל וטוב כו' שבודאי כבר מתוקן ומקובל מצד עצם אמיתתו ולכך נק' היכל הרצון שלמעל' מהיכל אהבה וגם בו אתדבקו' רב\"ר הוא משפיע ומקבל שהן ב' מיני אהבות דאו\"י ואו\"ח הנ\"ל באהבת דק\"ש (ובסמיכת גאולה לתפלה הוא בהיכל ק\"ק ששם גופו של יחוד משפיע ומקבל שלמעלה מאה\"ר דרצון שבאמת ויציב וכמ\"ש ביאור כל זה במ\"א באריכות) וזהו וזוכר חסדי אבות פי' אבות הן חו\"ב המולידים המדות ונמשך מהן מוחי' חדשי' תמיד שנק' חסדי (כמו יזכור חסדי אבות לבנים כך גם לאחר הסתלקו' אורו' דאו\"א כמו כי אבי ואמי עזבוני וה' יאספני להותו זוכר חסדי אבות לבנים כו') ומביא גואל גם לב\"ב פי' בנים הן מדות ודבור בן ובת בחי' זו\"נ וב\"ב הן הנולדי' מיחוד זו\"נ והוא התולדה מבחי' נה\"י דזו\"נ וב\"ב כבנים להביא גואל להם כמו אם יגאלך טוב שהוא בחי' יסוד כו' וזהו שבחי' יסוד דאו\"א מאיר עד כל נשמ' פרטי' שנולדה מיחוד זו\"נ דאבי\"ע ונק' בשם צדיק יסוד עולם וז\"ש ומביא גואל לב\"ב כו' עד גם מי שאין לו רק נפש דעשי' נמשך בחי' הגאולה הזאת שנק' גואל ישראל וכמו שכתוב ועמך כולם צדיקים (וגואל ראשון בחי' יסוד אבא בחי' משה וגואל אחרון משיח יסוד ע\"י ושניהם נקרא טוב כנ\"ל) וכל זאת ההמשכה רק למען שמו באהבה פי' למען שמו שהוא בחי' המל' שרש כנ\"י למטה והכל באהב' דהיינו ע\"י יחוד ב' אהבו' דאו\"י ואו\"ח הנ\"ל שבהיכל הרצון דאמת ויציב ואהבת דק\"ש שמזה נמשך מוחי' חדשי' גם לאו\"א להיו' נק' חסדי אבות והוא ע\"י מזל ונוצר ונקה שמקבלי' מאל עליון בחי' א\"א דאצי' כידוע בענין אל עליון קונה שמים וארץ וזהו אל עליון גומל חסדי' טובי' דע\"י וכמו ונוצר חסד ועושה חסד לאלפי' חו\"ב כו' שזהו קונה הכל כמו קונה שמי' וארץ משפיע ומקבל יחד (כענין קנה חו\"ב וב\"פ קנה ש\"י וב\"פ ש\"י תר\"ך שזהו בחי' אור הכתר עצמו שכולל"],[1700400419,"הכל) וכל זה בא מהתחלה הראשונה דהעלא' מ\"ן דכנ\"י מלמטה דכנ\"י מלמטה למעלה בבחי' בליטה באהבה דרצוא הנ\"ל משום דרוח אייתי רוח כמוהו בחי' אור עצמות חסד עליון להיות זוכר חסדי אבות לב\"ב כו' והיינו מ\"ש למען שמו באהבה דרצוא הנ\"ל שמזה נמשך ממילא אה\"ר העליונ' להיו' בוחר בעמ\"י באהבה מלמעלה למטה כו' ונמצא פי' למען שמו באהבה יתפרש על ב' אהבו' דרצו' ואהב' עליונ' שנמשך עי\"ז דרוח אייתי רוח כו') ובאמת באהבה זה קאי על עצמו' האהבה כמו שאוהב א\"ע כב\"י וכמו ואהבתיך כו' וזהו למען שמו גי' רצון הוא רצון דאה\"ר העצמי שישראל עבמ\"ת והכל א' וד\"ל):\n[לג] <b>והנה</b> מכל הנ\"ל נתבאר ביאור ענין ב' חותמו' הנ\"ל ע\"ד העבודה בב' מדרגות דרו\"ש ומעתה יש להבין שרש ענינם ע\"ד הקבלה איך שהוא למעלה והקדמה לזה יש לבאר תחלה בענין א' הנז' בע\"ח בכמה דוכתי בענין עליות העולמו' שנק' בשם העלאה כמו עליות העולמו' בשבת וכמו לע\"ל כו' היינו שעולם התחתון עולה למעלה להלביש לעולם העליון הימנו הרי ודאי שהעלא' זאת שהתחתון עולה הוא עולה בבחי' פנימי' שבו דוקא כדרך כל עלול שמתקרב לגבי עילתו בבחי' הפנימי' שבו דוקא ומה הוא מלביש ודאי אינו מגיע להלביש רק לבחי' חיצוניות שבעליון כי לפנימי' שבעליון לא ישיג לעולם (כמו בחי' ה\"ס ראשונו' דעלול מלביש ה\"ס אחרונות דעילה כמ\"ש בפרד\"ס בכל עו\"ע שהתחתון מלביש לעליון רק לחציו האחרון וכן רק חציו האחרון דעילה מלובש בחצי העליון דעלול כו') וכמו בחי' כחב\"ד דמל' מלביש לתנה\"י דז\"א וכן כחב\"ד דז\"א מלביש לתנה\"י דאימ' כו' וממילא אינו מלובש רק תנה\"י דז\"א במל' כו' (אך א\"כ איך נק' העלא' מאחר שדרך ההתלבשו' כן היא דחיצוני' שבעליון מלובש בתחתון ופנימי' שבתחתון מלבישו דודאי זהו כל עיק' ההשתלשלו' דעו\"ע דמחיצוניו' העליון נעשה בחי' פנימי' לתחתון כמו מנה\"י דאימ' נעשה מוחין לז\"א וכן מנה\"י דז\"א לנוק' כו' ולפ\"ז מהו ענין עליו' העולמות כמו בשבת שעשי' עילה ביצי' ויצי' בבריאה ובריא' באצי' מהו ענין עלי' זאת אם פנימי' עשי' עולה להלביש לחיצוניות דיצי' וכן מיצי' לבריאה ומבריאה לאצי' אין כל חדש בזה שגם ביומין דחול חיצוניו' דיצי' מלובש בעשי' בפנימי' שבה כו' ועד\"מ משפיע ומקבל שבודאי רק חיצוניו' השפע שבמשפיע נעשה ונמשך במקבל להיו' לו לפנימי' אור וחיות וכמו שכל הנמשך בדבור למקבל שבדבור אין שם רק בחי' חצוניו' השכל ולמקבל מן הדבור נעשה לו מוחי' השג' פנימי' שלו וראי' ממה דלא קאים אדעתי' דרבי' כו' וד\"ל אך הענין הוא כידוע דג' עולמות בי\"ע זהו כמו מחשבה ד\"ומ למטה חיצוני' אותוית הדבור מלובש במעשה נעש' מזה פנימי' העשי' שהוא רצון ושכל ומדות דעשי' כחב\"ד וחו\"ג כו' דעשי' וכן ביצי' שהוא הדבור מלובש חיצוניות אותוית המח' דבריאה שמזה נעשה פנימי' מוחי' בדבור ונק' מחשבה שבדבור כו' וכמ\"כ ממדות שבלב ודבור כו' וכך הוא במדות שבלב לדבור מהשגה חיצוניו' דבינה ובינה מחכמה וחכמה מרצון ורצון מלמעלה מן הרצון כו' וכל זה נק' התלבשות עליון בתחתון בדרך ירידה מלמעלה למטה (שזהו בחי' יושר משא\"כ בחי' עגולי' בחי' התכללו' נהפוך הוא מן ההתלבשו' כמו האופן בתוך האופן שלא ישיג העלול לעילתו כלל אדרבה מוקף הוא בתוכו ונק' בחי' התכללות תחתון בעליון כמ\"ש במ\"א והעליון מכולם משובח מהכל והוא הרצון שבו מוקף מרחוק השכל ובתוכו המדות וזהו בי' חותם השני כמו שית' בסמוך כו') והנה בשבת שאז זמן עליות העולמו' דעשי' עולה ביצי' כנ\"ל הענין הוא דבחי' המוחי' שבמעשה עולה למעלה לדבור שביצי' וכן מיצי' לבריאה היינו שבחי' פנימי' שבדבור שהוא כמו כחב\"ד שבו עולה למעלה במחשבה דבריאה וכמו ממצוא חפצך ודבר דבר שבפנימי' הדבור עולה למעלה כו' עד\"מ כששובת אדם מפועל ידיו דמה שהיה בזה שכל ורצון כו' הכל עולה למעלה בנוחו מהתייגע בשכלו עוד בעשי' זו (הגם שפועל בידיו כמתעסק כו') וכך כששובת הצמצום שכלו בדבור הרי עולה מחשבת שכל ה שבדבור למעלה במחשבה ונמצא בחי' חיצוניו'"],[1700400420,"המחשבה שהיה מצומצ' בדבור עלה למקומו במוח המחשב' ונעשה מפנימי' התחתון חיצוניות להלביש עצם כח המחשב' ואע\"פ שהיה נחשב מחשבה זו בחי' פנימי' בדבור בעלותו למעלה נק' חיצוניות אמנם לא שנכלל ממש אלא מלביש לעצם כח המחשבה וכן במחשבה עצמה הרי בחי' פנימי' המוחי' שבה עלה למעלה ומלביש לעצם כח השכל בבחי' חיצוניות כו' וא\"כ לכאורה יש להבין בזה מה יתרון יש לעליי' מחשבה זו שבדבור כשמלבשת למעלה לעצם כח המחשב' הלא גם טרם ירידתה בדבור היתה מלבשת לפנימי' המחשבה ברוחניו' ודקו' אותיו' המחשבה כו' וגם בירידת' בדבור הוא אותה המחשבה עצמה עו' הענין הוא דבדבור מלובשת בהעלם ולא בגילוי ובעלותה למקומה מאירה בגלוי אור (וכמ\"ש במ\"א בענין לדוד בשנותו שפושט בגדי חול ולובש בגדי שבת שהוא אור הבריא' כמו שהוא טרם התלבשותו ביצי' משא\"כ בחול שמלובש בהעלם בדבור בחי' יצי' כו') וכמ\"כ עליי' יצי' שבעשיה למקומו שהדבור בא בהעלם בהתלבשות במעשה כמו לצוות לעשות ויוצא מהעלמו כו' (וכך עליי' המחשבה מהתלבשותה בהעלם באותיות מחשבה דבריאה שהוא עליי' בריא' באצי' כו') ונמצא יש יתרון מעלה בעליות הללו בשבת דוקא כנ\"ל ואמנם מובן מזה דפנימית שבתחתון שנעשה מחיצוניות שבעליון שירד ממקומו להתלבש בתחתון בהעלם היא שעולה לעליון להלביש שם בבחי' חיצוניו' שזהו עיקר ענין העליות בשבת משא\"כ בחול שבאים דרך ירידה מעליון לתחתון כו' ובזה מתורץ הקושיא דלעיל מה שנקר' העלא' היפך דרך התלבשות מחיצוניות שבעליון כידוע שעיקר העליות הוא בפנימית העולמות וד\"ל והנה בחי' העלא' דפנימית שבתחתון למעלה להלביש לעולם העליון הימנו נקרא בשם בליטה כאותיות חותם הבולט וכבליטת ההר העולה בגובה כו' מאחר שעולה מלמטה למעלה ממיצר וצמצום שלו בתחתון כו' למעלה ממדרגתו הרי ודאי ענין יציאתו זה נראה בולט ביותר ככל דבר העולה מנמוך לגבוה (וכמו כן עליות הנשמות והמלאכים מנמוך לגבוה בכל שבת כמו מג\"ע התחתון לג\"ע העליון דכתיב והיה מדי חודש כו' דרך העמוד נראה בולט כו' כמו יוצאין בשיר כו') והיינו בבחי' התפעלות יש ודבר מורגש בעלותו כמו בחי' רצוא הנ\"ל ומבואר למעלה דרוח אייתי ואמשיך רוח כמוהו גם כן בבחי' יש כו' הענין הוא כידוע דבשבת יש עלי' וירידה (שאחר עליות העולמות בליל שבת נמשך מלמעלה למטה ביום כו' והיינו ב' שבתות כהלכתן כמ\"ש במ\"א) והרידה הוא לחזור האור העליון שיומשך ויבא בתחתון (להיות מזה ו' ימי חול כידוע) בבחי' התלבשו' בהעלם וצמצום כמקדם דהיינו חיצוניות שבעליון שעלה למעלה הוא שחוזר ויורד להתלבש בתחתון להיות שם בהעלם וצמצום עד\"מ בשביתה יש ב' הפכי' תחלה ישבות בהעלאה שכח המעשה המתפש' יעלה אל העליון הימנו וכן יעלה לעליון הימנו וכך הוא בכל חלקי נרנח\"י והב' השבית' שנק' נייחא כמו שתשוב רוחו אליו שזהו בבחי' ירידה והתפשטות למטה) והנה בחי' ירידה זו שיורד למטה הוא בא ג\"כ בבחי' יש ודבר כו' מאחר שמתצמצם ובא בהתלבשות בכלים דהיינו מה שנעשה בחי' אור וחיות פנימי לתחתון לפי הגבלת הכלי שלו שזהו בבחי' כמו בחי' שוב הנ\"ל בהתלבשות אורות בכלים ע\"י המצות שנק' בחי' שקיעה ולא בליטה שהרי התלבשות זו באה בהעלם שמתעלם האור ונכנס בתוך עולם התחתון להיות לו לאור וחיות פנימי כמו אותיות השקועים שמקבלים כנ\"ל והיינו לפי שההעלא' היה בבחי' יש להלביש לעליון כנ\"ל ע\"כ אייתי רוח כמוהו לבא ג\"כ מעולם התחתון בעליון בבחי' יש דהיינו בבחי' לבוש וצמצום כנ\"ל וד\"ל (ויתרון התלבשות זו שאחר העליי' ידוע בענין התשבחות דכל שבח נמשך אור חדש לחדש מע\"ב שלא הי' עדיין כו' וכמ\"ש במ\"א)\n[לד) וזהו בחי' חותם הראשון שמבחי' בליטה דלמטה נעשה בחי' שקיעה דהיינו שלמעלה נמשך האור בתחתון"],[1700400421,"בהתלבשות בכלי כנ\"ל (והוא מפני שמלמטה למעלה עלה בבחי' יש בב' דברים א' גופה של ההעלא' שעולה מצמצום דלמטה עולה בבבחי' יש כנ\"ל והב' והוא העיקר שהוא דלאחר שעולה הוא מלביש לעליון דהלבשה זו בחי' יש בולט יותר להעלים בתוכו פנימית העליון כמו אותיות מחשבה שמלביש לפנימית הכוונה שבמחשבה) וזה מובן ע\"פ הקדמה הנ\"ל בענין ההעלא' דעליות העולמות הנז' בע\"ח ומעתה יש להבין ענין החותם השני שהוא בהיפוך דמשקיעה דלמטה נעשה בחי' בליטה מלמעלה כנ\"ל וזהו יובן ע\"פ הקדמה אחרת הנז' בע\"ח ג\"כ בענין העלא' בהיפוך מהעלא' הנ\"ל דהנה העלאה הנ\"ל אין עיקר ענינה רק בהתלבשות שמלביש לעליון בעלותו שנראה ליש ודבר נגלה מבחוץ להעלים בתוכו הפנימי' שבעליון כנ\"ל אבל ענין ההעלאה אחרת יש שנק' בחי' התכללות תחתון בעליון כשעולה שם נכלל ומתאחד בו ונתבטל מהותו שם כאילו אינו במציאות בפ\"ע כלל וכלל כו' והוא כמו בחי' עיבור הולד בבטן אמו שנכלל בה ולא ניכר במציאות כלל כו' כך התחתון נכלל בעליון ממש ולא שהו' מלבישו כהעלא' הנ\"ל וזהו הכלל לכל בחי' העלאת מ\"ן בכל מקום שזהו בחי' התכללו' דעלול בעילתו (כדוגמת בחי' עלולי' הנ\"ל שהשכל נכלל ברצון והמדות נכללים בשכל כו' כידוע שהרצון למעלה מן הטעם ומה שיש טעם לרצון נכלל בו בהעלם ועיבור ולא ניכר במציאות כלל וכן בשכל יש בחי' מדות בהעלם ועיבור [ונק' עיבור ז\"א בבטן אימא כמשי\"ת] וכמו אותיות השכל שנכללים בעצם המושכל ולא ניכרים כלל וכך נכלל הדבור במחשבה והמעשה בדבור כו') ויובן דבר זה מבחי' ז\"א שהוא המדות שהוא בבחי' עיבור בבטן אימא כו' דהיינו שבהשג' דבינ' נכלל התפעלות המדו' בהעלם כמו שאנו רואי' באדם שטרוד בעצם השכל נכלל ועולה שם התפעלות הלב ואינו נק' העלא' זו הלבשה לשכל אדרבה העלא' זו התכללות ובטול מהות המדות בשכל וכן בטול והתכללות השכל וטעם ברצון כו' שהוא בחי' בטול בתכלית (וכמ\"ש במ\"א בענין ואל משה אמר דלא ידיע' בשם וכן א' זעירא דויקרא וכה\"ג) ובחי' עיבור דתלת גו תלת כו' היפך זה דחב\"ד וחג\"ת מתעלמי' בהעלם בנה\"י שזהו כמו במדו' טבעיים דתינוק יש בו בהעלם ועיבור אור העליון מהם שהוא המושכל של המדו' כשיגדל ויבאו בגלוי דלפי שכלו יהולל איש כידוע וקודם שיגדל המוחי' בהעלם כו' ה\"ז העלם ועיבור דעליון בתחתון כענין התלבשו' הרצון בשכל וטעם שהוא בא שם בצמצום והעלם והטעם מלביש לרצון וכך השכל בהעל' במדות כו' שזהו כענין הנ\"ל בהתלבשות עליון בתחתון דרך ירידה כו' שזהו היפך מענין התכללות תחתון בעליון דכאן כו' ומה שית' דלידת הולד בא מצד העלמו בבטן היינו מחמת העלם המדות בשכל הנק' התכללות ולא מחמת שהוא תלת גו' תלת כו' דהעלם זה מעליון לתחתון (ובאמת דוקא מצד העלם דתלת גו כו' יבא סיבת הלידה שמתהפך ויוצא כו' ושרש ענין זה מבואר במ\"א בענין תיבת נח כו' ובענין עמדתי לפניו דאליהו דאשתוהי אשתהי יב\"ח כו' דהיינו העלם המוחי' יותר גורם לידת המוחי' כו') והנה על דרך משל מהעלם הולד בבטן אמו שנכלל באמו ונתעלם שם בהתכללו' כו' מזה העיכוב בהעלם ט' חדשי' בעיבור בא סיבת לידת הולד כך הוא ענין לידת המדות מן השכל שנק' בינה אם הבנים שזהו ענין בצאת ישראל ממצרים ממיצר מי דבינה שהי' ז\"א בבחי' עיבור בבטן אימא כמבואר במ\"א באורך וביאור זה דרך קצרה היינו בחי' העיבור והתכללו' המדו' בהשגה תחלה שמזה דוקא יבא בחי' לידה של המדו' שהוא ענין גילוי מציאו' שלהם במהות בפ\"ע כידוע (ודוקא ממה שהי' הולד מקופל ראשו בין ברכיו כל ימי העיבור שזהו ענין תלת גו תלת הנ\"ל ואמנם אין פי' העלם דתלת גו' כו' כנ\"ל דהיינו העלם המוחי' חב\"ד וחג\"ת בנה\"י כהעלם עליון בתחתון כו' אלא אדרבה זה ההעלם הוא בבחינות התכללות תחתון בעליון ממש דהיינו שהמוחי' דולד ומדותיו הן בהעלם בהתכללו' למעלה שזהו כמו דוגמת השינה שאדם בשעה שישן שכלו"],[1700400422,"ומדותיו בהעלם ג\"כ והיינו שהן בבחי' עלי' והסתלקות והתכללות בנפש ולא באין להאיר במוח ולב רק ברשימו בעלמא כמו כח המדמה שבמוח וכן קיסטא דחיותא שבלב בחי' רשימו מהמדו' כו' כך הוא בחי עיבור דולד שראשו בין ברכיו כו' דודאי כל מה שיש בו מוחי' ומדו' הכל הוא בבח'י עלי' והסתלקו' שזהו בחי' התכללו' ממש באמו שהרי אוכל מה שאמו אוכלת כו' וכירך אמו הוא כו' כמ\"ש במ\"א ומ\"ש תלת גו' כו' דחב\"ד וחג\"ת מתעלמי' בנה\"י הוא עד\"ז דוקא דהיינו שהן בבחי' ההעלם והתכללו' למעלה במוחין דאמו כו' ומ\"ש דמתעלמים בנה\"י לא שמתלבשין ושורין שם כהתלבשות הרצון בשכל הנ\"ל אלא שהן שם בכח והעלם ולא בגילוי וכאשר יולד יוצאים מעט מעט לגילוי במשך זמן גדלותו כידוע וא\"כ לפ\"ז נהפוך הוא דאדרבה משום שהיו המוחים דולד בהעלם ועיבור ט\"ח שהוא דוקא בחי' ההתכללות ממש בבטן אמו לזה בא סיבת לידת הולד במהו' בפ\"ע דהיינו בחי' לידת המוחין כנ\"ל כמשי\"ת וד\"ל) והנ' ע\"י בחי' התכללו' המדות תחתון בעליון עי\"ז נמשך אח\"כ מן העליון בחי' מוחי' חדשי' לגמרי למדו' בבחי' אור חדש ולא האו' הסתלקות נה\"י דאימא כו' ונמשך מוחי' חדשים למדות שנולדים והיינו שלא בא האור העליון למטה בבחי' לבוש וצמצום והעלם כלל אלא בחי' גלוי אור חדש שאינו בא בבחי' כלי ולבוש כלל (עד\"מ ע\"י התכללות השכל והשגה הראשונה למעלה מן השכל בכח עצם השכל ההיולי נמשך עי\"ז מכח המשכיל אור שכל חדש (כמ\"ש במ\"א בענין סייג לחכמה שתיקה שהשתיקה הוא התכללות ובטול השגה הראשונה לכח השכל ועי\"ז נמשך מוחי' חדשי' לגמרי כו' או עד\"מ תלמיד דטריד למיבלע שנכלל בכל כח שכלו בבחי בטול המהות בשפע שכל ששומע מרב מזה נמשך לו אור שכל חדש להשכיל חדשות במה שקיבל שנק' תולדה כו') (אך מה שבא האו' בלי לבוש וצמצום כלל זהו בא מצד התכללו' בעצם שממשיך רוח חדש מעצמו' בלי לבוש חצוני כלל משום דרוח אייתי ואמשיך רוח כמוהו ממש ואם ההעלא' הזאת באה בבחי' בטול המהות בלי לבוש ויש אדרבה הפשטת היש בהיותו נכלל בעליון והי' כלא כו' מזה נמשך רוח העליון ג\"כ בזה האופן שהוא בלי מהות ויש כו' דהיינו שאינו בא בהתלבשות חיצוניות כלל (ומובן זה בלידת המדות שהמוחי' שנולדו עם המדות הן בחי' עצמיים כמו שהמה ממקורם וראיה לזה ממש שיגדלו מעט מעט מעצמם ואם היה בדרך לבוש וצמצום לא היה נתוסף גידול שכל ומדות כלל רק כמו הראיה שמתלבש בכלי העין שלא יוסיף ויגרע וכן לבוש המחשבה במוח וכלי הדבור בגדול כו' (ומה שהתנוק יגדלו איבריו וכן יגדלו לבושיו דמחשבה דו\"מ זהו ג\"כ מצד הלידה מאחר שנולד בחומר וצורה הרי כמו שהצורה תגדל להיותם בבחי' עצמיי' כך יגדלו כליהם) ומכל זה יובן ענין החותם השני שהוא בהיפוך מהותם הראשון דהיינו שע\"י בחי' השקיעה דלמטה נעשה בליטה מלמעלה כנ\"ל דהיינו בחי' בטול והתכללות שנכלל ובטל בעליון רוח אייתי ואמשיך כמוהו רוח העליון שיומשך בבחי' בליטה מלמעלה דהיינו בחי' גלוי אור חדש מעצמו' המאציל באצי' שלא בא בבחי' כלי ולבוש כלל וכמו שיהיה לע\"ל דכתיב ולא יכנף עוד כו' כנ\"ל שזהו למעלה מאור הגנוז ומלובש ברמ\"ח איברין דמלכא ע\"י מעש' המצות וכל זה מפני שהעלאה זו שנק' העלאת מ\"ן כנ\"ל אינה באה למעלה בבחי' יש להלביש העליון כו' וגם בעלותו מלמטה אינה בבחי' יש אדרבה הכל בבחי' המהות רק בעלותו מלמטה נק' בטול היש לבד ובעלותו שנכלל ובטל ממש בעליון היינו בחי' התכללות ובטול בעצם ממש ולזאת רוח אייתי רוח כו' להמשיך אור העליון בבחי' בליטה דהיינו שאינו מתלבש בבחי' כלי בהעלם וצמצום כו' (וכנ\"ל בהפרש שבין בחי' רצוא ושוב בדרך העבודה)"],[1700400423,"(לה) <b>ומעתה</b> יש להבין ענין מארז\"ל דכל אות שאין גויל מקיף לה מד' רוחו' פסול' הנ\"ל והנה תחלה יש להקדים בשרש בחי' האותיו' מה הן בהיות נודע בפי טעם קריאת שם אות על היות שכל אות הוא ענין המשכה שהוא רק ענין הגלוי מן ההעלם שבעצם והוא ענין ביאה בלה\"ק שתרגומו ואתא כמו כאשו יבא אדם לבית שזהו ענין גלויו לכל ואין כל חדש בעצם מהותו רק שלא הי' נגלה לכל ובביאתו נתגלה ולכך תרגום של ובא ואתא וזהו פי' אות ל' אתא שבתרגום כו' ובאמת פי' אות בלה\"ק היא בחי' הסימן וכמו רושם ציון לדבר מה שיהי' לאות ולזכרון כל הימי' על עצם הדבר שבראותו האות יהי' נזכר עליו כמו אות הוא ביני כו' וכן בקשת והי' לאות כו' (וגם פי' אות ומופת כמו ולכל האותו' והמופתי' כו') והיינו ג\"כ רק ענין סימן וראי' לדבר מה הנעלם מעין כל שעי\"ז האות בא לידי גלוי מהעלמו והוא ג\"כ ענין האותיו' שהן כמו רק רשומי' וציונים לדבר מה הגנוז ונעלם שהוא אור החכמ' שהאות מורה עליו לפי מה שהוא כאות האלף שאופן ציורו ותמונתו מורה כמו רושם וציון לבד על עצם האור הגנוז בו כמו שהוא דוקא וכמו אאלפך חכמ' בחי' הכתר דחכמ' וכה\"ג אות בי\"ת באופן ציורו מציין לדבר הנעלם שהוא אור החכמ' בבינה כמו בחכמ' יבנה בית כמו שא' הדרדקי אלף בית אלף בינה כו' (ומבואר במ\"א בהפרש שבין עצם התמונה של אות כמו שבא בכתב לקריאת שמו בע\"פ כמו אלף בתוס' ל\"פ בקריא' שנק' מילוי וגם זה צריך טעם למה יקרא תמונה זאת בשם זה ותמונה זולתה בשם אחר כמו ציור זה דא' שמו אלף וציור הב' שמו בית ולא להיפך וה\"ז כמו קריאת שמות אדם ראובן או שמעון שהשם שייך לעצם שזהו שמו דוקא והכל עולה לסגנון א' דאותיו' הן רק הוראה וגלוי אור העצם כמו שהוא דוקא ע\"כ בא אופן ציורו כך וכך ולא באופן אח' וא\"א להיו' בקריא' שם אחר ואמנם לא כרושם בעלמא שאינו מורה כלל לפי העצ' ממש רק בחי' זכרון לבד אלא אדרב' האות מגל' ומורה על העצם הדבר כמו שהוא בלי שינוי כלל רק שאינו עצם הדבר אלא בחי' גלויו (ולא כמו ובא בלה\"ק שהעצם בא) ונהנה מעתה יש להבין בבחי' האותיות למעלה כמו אותיות שנבראו בהן שמים וארץ וכל צבאם כידוע דאותיות יהי אור מהווה את האור מאין ליש בכל רגע וכן אותיות יהי רקיע מהווה את הרקיע מאין ליש בכל רגע כו' וכך בכל הברואי' שבכל העולמות הכל מתהוו' רק מאותיו' וצרופי' שונים וכידוע במא' דס\"י ה' אבנים בונות ק\"ך בתים כו' וכמ\"ש בדבר ה' שמים כו' וכל אות ואות הוא בחי' המשכה מיוחדת דוקא וצירוף האותיות הוא בחכמה דאבא יסד ברתא והיינו בראשי' נמי מאמר הוא כידוע שהוא הצירוף בחכמה שנק' בראשית מאמר אחד שכולל הכל כו' ודרך כלל ו' ימי בראשית מא' יהי אור כולל אלף שנה כמ\"ש כי אלף שנה כיום כו' והיינו מבחי' חסד דאצי' שנק' יום א' נמשך מא' יהי אור וכן מא' יהי רקיע ביום ב' מאצי' לבי\"ע כולל אלף כו' מבחי' הגבורה דאצי' וכך ו' ימים דאצי' מקוריי' כלליי' לו' אלפי שני דהוי עלמא כידוע ולפי זה הרי מובן עכ\"פ בין דרך כלל ובין דרך פרט הרי האותיות שנבראו בהן הכל הן בחי' ממוצעי' בין העצמות להעולמו' והברואי' מאחר שנבראו מהן הכל נקראו האותיו' האלקיי' בחי' בורא ומהווה כמו אותיו' יהי אור הן אותיו' אלקיי' שמהווה ובורא את האור מאין ליש כנ\"ל וכך דרך כלל בו' אלפי שני כו' הרי אותיות יהי אור הכולל אלף שנה שנמשך מבחי' חסד דאצי' הוא בחי' ממוצע בין עצם אור חסד דאצי' לעולמו' ומלאכי' שנבראו מבחי' אותיו' הללו דמדת החסד כו' וכך הוא בחי' האותיות דיהי רקיע שנמשך מבחי' אור הגבורה דאצי' נק' ממוצע עד\"ז ממש כו' וד\"ל וענין ממוצע ידוע שהוא המחבר ומקשר עליון בתחתון ובכאן ג\"כ הענין של אותיו' האלקיי' דיהי אור ויהי רקיע וכה\"ג הן ממוצעי' להביא ולחבר העליון בתחתון שזהו להביא ולהמשיך מעצמו' אורו' דחו\"ג דאצי' להיות בחי' התפשטו' וגלוי שפע"],[1700400424,"האלקי להוות העולמו' כמו אור ורקיע למטה בפרט ולמעלה הן ב' אלפי שנה כו' וגלוי והתפשטות אור האלקי להוות הבריאה ליש בתמידו' הן הנה גופי האותיו' האלקיי' הללו שמהן ועל ידן דוקא נמשך שפע האלקי וכנ\"ל (ואין זה מובן לכאורה דאין זה דומה לממוצע שהממוצע מביא ומחבר לעצמו' העליון בתחתון כידוע ובכאן הרי השפע שנמשך לעולמו' אינו רק מבחי' האותיו' עצמן שנק' מהווה כנ\"ל ולא מבחי' העצמו' דאורו' דאצי' ואיך נק' ממוצע כו' אך שרש הדברים הוא כמבואר במ\"א דהאותיו' הן בחי' כלים מגבילי' האור כמו אותיו' השכל שמגבילי' לאור העצם ואע\"פ שהן מתארים תואר השכל אין זה רק לגבי העלול מן השכל כמו התפעלו' המדו' שנולדי' מן השכל שהמדו' מהות אחר נבדל ומרוחק בערך ממהות השכל והנה אנו רואי' בחוש שבלעדי אותיות השכל לא הי' חיבור וקשר כלל בין השכל והמדו' שיהי' התפעלו' המדו' מן השכל כי לא קרב זא\"ז כלל ואם הי' מתבונן בדבר מה אם לטוב או לרע הי' נשאר הענין בשכל ולא הי' בא לכלל התפעלו' מדו' אוי\"ר אהבה לטוב וירא' מן הרע כו' רק ע\"י אותיו' השכל שהוא גילוי השכל ותוארו הבא בהגבלה הוא המביא שפע השכל לבא ממהו' למהו' שהוא בחי' המדו' והיינו שאנו רואי' שמיד שיתבונן באותיו' באותיו' מחשבת שכל לטו\"ר מזה יתפעל במדו' שהוא אוי\"ר ולפ\"ז עיקר המביא עליון בתחתון הוא אותיו' השכל ולכך נק' בחי' ממוצע וגם זה אמת שהאותיו' עצמן נמשכי' ומתפשטי' במדו' ולא גופו ומהותו של השכל כמו שהוא שא\"א שיתפעל במדו' במהו' שכל ממש כו' אבל עכ\"ז האותיו' הביא ו תולדה זו מן השכל למדו' וה\"ז עד\"מ הכלי שהוא ממוצע לחבר ממהות למהות זולתו ככלי הסכין שמחבר התנועה שביד בנחתך וכה\"ג כלי ההבטה שמחבר הראי' למרחוק וזה נק' כלים פשוטים ואותיו' השכל נק' כלים מקבלים שמקבלי' אור השכל ומשפיעי' למדו' ככלי הכוס שמריק מה שבתוכו כו' וכך הוא באותיו' המדו' שבלב להיו' שהמדו' בלב ג\"כ הן אורו' פשוטי' ומוגבלי' באותיו' הנק' כלים שנק' אמ\"ר רוחני שבלב שמביא ממהו' הלב למהו' דבור והוא נק' קול כידוע והיינו סיבת החיבור שיש לאותיו' הדבור וכמו באותיו' הבל הדבור שמקבל מהבל הלב (וכן אותיות המחשבה שנק' הרהורי לבו כידוע) ונק' ממוצע בחיבור קשר ממהות הלב למהות דבור ע\"י אותיות הבל הלב שהן בחי' כלים מגבילים לאורו' כו') (ויובן כל זה למעלה בכל התהוו' עו\"ע שא\"א להיו' כ\"א ע\"י ממוצע כמו אורות חו\"ג דאצי' כשבאו במאמרות יהי אור ורקיע הוא נמשך ע\"י ממוצע שהן אותיות דיהי אור כו' כנ\"ל דהבל הלב ואותיות הדבור שנבראו מהן האור והרקיע הרי הן מחברי' ומקשרים המדות באור ורקיע תמיד להיות התהוותם תמידי' מאין ליש כו' וכך הוא למעלה מזה גם במקור האורות דחו\"ג דז\"א שהן בחי' אותיות דבינה שנמשך למדו' דז\"א דאצי' שזהו עד\"מ למטה כשנמשך אותיו' השכל במדות להחיותם שבחי' גילוי זה מן השכל למהו' מדה נק' ממוצע לפי שמביא ממהו' שכל למהו' מדה כנ\"ל וכך הוא בכל עו\"ע עד רום המעלות כידוע) (וכמ\"ש במ\"א בענין ז' הבלי' עלאי' וז' הבלי' תתאי' שהן בג' מדרגות הנ\"ל ז' הבלי' דבינה במדו' וז' הבלי' דמדות בדבור וז' הבלי' דדבור בעולמות וכל א' מאלה נק' הבל דמיני' אתעביד קלא רק שזה נק' קלא פנימא' כו' ועתיד לצאת בגלוי כו'):\n(לו) <b>והנה</b> יש בענין האותיו' ב' מדרגות א' כמו אותיו' החקיקה שהן אותיו' בעצם כאותיו' החותם וכה\"ג והב' אותיו' שהן כתובי' בדיוע\"ג הקלף שהן דבר נבדל מן העצם דקלף [כנ\"ל באות כד] והדמיון לזה הוא נמצא גם באותיו' השכל ומדו' ומו\"ד דאותיות העצמיים שבשכל הוא שנתפשטו במדו' וכמו שטבע השכל בעצם להתחקק באותיו' שנק' גלוי אור השכל כמ\"ש במ\"א נק' אותיו' העצמיי' שבו ומה שנתפשט הארתן"],[1700400425,"במדו' להיו' שם לאור וחיו' הרי זה כאותיות החותם שנחקקו' בדבר נבדל כו' וכן אותיות עצמיי' שבמדות כשנחקקי' במחשב' וכן אותיות עצמיי' שבמחשבה בדבור וכן מאותיות הדבור שנחקקי' בהבל האויר לחוץ ממש ונקרא בחי' התפשטו' מעצם האות למהו' נבדל הימנו בשם דילוג הערך וצמצום גדול ומכ\"ש מאותיו' מו\"ד כשבאין בציור תמונה בכתב שהוא דילוג יותר מדילוג הערך דהבל הדבור כשיוצא נפרד בהבל אויר הארץ שעכ\"פ השומע קול הברה זו מקבל מגופו של הבל חי שבדבור שיצא לאויר משא\"כ באותיו' הכתב שאין בהן רק רושם מעצם חיות התנועה שביד הכותב ע\"פ אותיו' הדבור או המחשבה כו' [ולכך רחוק ערך המקבל מתוך הכתב למקבל מתוך הדבור דעכ\"פ קאים אדעתי' דרבי' כו' כמ\"ש במ\"א] והנה ידוע שהבל הדבור דמיני' אתעביד קלא היותא לאויר העולם שהוא בבחי' נפרד ואינו רק מותרו' וחיצוניו' חיו' הדבור מ\"מ יש בו גם מפנימי' החיו' שבהבל הלב שמלובש בדבור שהרי דברי' שיוצאי' מן הלב נכנסי' ללב שומע קול הדבור הנפרד וגם אור פנימי' הרצון ועונג ושכל שבלב נכנס ללב המקבל כו' א\"כ ודאי גם בדילוג ערך זה אינו נק' הפסק והבדל לגמרי אדרבה יוכל לבא שם כל הפנימי' והעצמו' אע\"פ שאותיו' דשכל ומדו' ומו\"ד העצמיי' אינם נמשכי' בגלוי זה שמתגל' מהם כמו מאותיו' השכל למדו' כנ\"ל מ\"מ יוכל לבא כל פנימי' השפע למקבל מן הבל נפרד של הדבור כנ\"ל משא\"כ בחי' אותיו' הכתב שנבדלים לגמרי מכח וחיו' אותיו' המו\"ד וגם מאותיו' התנועה והמעשה דכתב כבר נפסק ולא נמצא שם רק רושם בעלמא שהוא בהעלם גדול כידוע וד\"ל (משא\"כ אותיות החותם שחוקק בשעוה שהרי עשה חקיקה עצמי' בשעוה ולא רושם בהעלם כמעשה הכתב כו' וכמו כן הכותב בדיו דרך חקיקה שחוקק בהן קולמסו כו' וכמו והמכתב כו' חרות על הלוחות כו') והנה יש עוד מדרגה הנחשב לבחי' אותיות והוא כמו ממוצע בין בחי' אותיות עצמיי' הנ\"ל לאותיות הכתב והיינו כמו אותיות היוצאים מהבל הפה לאויר העולם אך שנעשית נבדלים לגמרי אבל יש כדוגמתן ואינם נבדלים כלל אדרב' אחוזים וקשורים במקור חוצבן ואינן נק' אותיות עצמיי' ולא כאותיו' המתפשטים מן העצם כאותיות השכל שמתפשט במדו' וכן ממדו' למו\"ד כו' שזה בא בגילוי עכ\"פ אלא הן באים בבחי' דילוג גדול ובצמצום ובהעלם כערך אותיות הכתב הנ\"ל והוא ענין ובחי' השערות שיוצאים וצומחים ממותרי מוחים כידוע שיש לכל שער' ושערה גומא מיוחדת בפ\"ע במוח שמשם שרש חיות יניקתה ואמנ' השערה עצמה דבר נבדל לגמרי מעצם החיות שהרי כשחותכין אותו לא ירגיש כאב כלל כידוע אך כשימשוך אותה ירגיש כאב מצד שרש יניקתה בעצם הראש והמוחים שבו הגם שאינו רק בחי' מותרות בעלמא מ\"מ אחיזתה בעצם החיות ממש כצמיחת האילן משרשי יונקותיו וכה\"ג וכידוע שהשערות נק' בחי' צומח שבחי כו' (וכן צמיחת צפורן רק שהצפורן בא צמיחתו ממותרי לחלוחי' מוח שבעצמות והשערות ממותרי הדם) והנה החיות המצומצם ביותר בחלל השערה (וכמו הזיעה שנסחט מן השערה דרך חללה כך החיות נתצמצם בא מגומא שבראש כו') ה\"ז כדמיון הבל הדבור שיוצא באויר העולם הנבדל ועכ\"ז אינם דומים זע\"ז דהבל הנבדל באויר יוצא והולך לו ואין לו אחיזה ויניקה וחיבור עם הבל הפה מקורו [הגם שמתפעל השומע ממנו כמו מקול ערב דניגון שיוצא מהבל הלב כנ\"ל זהו מצד קצת החיו' הנשאר בו אבל נפסק ונבדל וקול הכינור יוכיח שמתפעל ממנו ג\"כ] משא\"כ בחיו' שבשערה הגם שהוא מצומצם ביותר אבל הוא אחוז וקשור בשרש יניקתו בגומא כו' כנ\"ל עד שמרגיש במשיכת השערה כו' ומכ\"ש שאין לשערות דמיון עם אותיות הכתב שאין שם רק רושם בעלמא ובהפסק וריחוק גמור כנ\"ל וגם זה א\"א לומר שיהיו בערך אותיות עצמיי' ממש כי אינן רק חיצוניות ומותרות שבאו"],[1700400426,"בבחי' צמיחה לבד כו' הגם שצמיחה זו עצמי' כצמיחת העלין על האילן וכעשב השדה מ\"מ נק' לבוש חיצוני בלבד כידוע (ומ\"מ נחשב מותרות עצמיות מצד שצמיחתן בלתי מוגבלת שחותכן וחוזרין וצומחין עד אין שיעור כעשב השדה כו') אך צריך לומר שהן בחי' ממוצע בין אותיות העצמיי' (ככלי המוחי' וככלי הגלגל' כו') ובין אותיות נפרדים לגמרי וגם לא כמו אותיות שמתפשטים מן העצם שבאי' בגלוי נבדל שהרי אינן נבדלים וגם אינן באי' בגלוי כלל כי אור וחיות שבשערות הוא בהעלם וצמצום גדול בדילוג הערך ביותר (וגם אין להם דמיון לאותיות הכתב שמתגלה בהן עכ\"פ הכל בחיצוניו' כו') אלא אמיתית דמיונם הוא כמו ענין הארת אור השכל במשלים וחידות שהמשל דבר זר והארת השכל מתעלם שם תכלית ההעלם והצמצום ומה שמבין השכל מתוך המשל בא אחר העלם המשל (ולא כאותיות הכתב שבהן נגלה אור השכל כמו באותיות הדבור רק שהחיות מצומצם בהעלם) וכך חיו' המוחים מצומצם בהעלם גדול בחלל השערה (ולא כאותיות המתפשטים משכל במדות שבאים בגלוי כו' ולא כאותיות מחשבה בדבור וכה\"ג כנ\"ל אלא כאותיות הדבור שנבדלים באויר אבל המשל מן השכל אינו נבדל כלל שמשל בלא נמשל כגוף בלא חיות כלל ולא כחומר וצורה שזהו כאותיות עצמיים הנ\"ל שהרי אין המשל רק לבוש לנמשל כידוע ועכ\"ז אינו נבדל אדרבה אחוז וקשור בנמשל ומשם חיותו והוא בא במותרות ונובלו' בלבד כמו השערות ממש) ואמנם הנה ידוע הכלל בכל שפע ע\"וע שכל שהשפע באה בקירוב הערך יותר יבא באופן בחי' אותיות שהן גלוי עצמות השפע בכל המדרגות דהיינו כמו בחי' אותיות שהן גלוי עצמות השפע בכל המדרגות דהיינו כמו בחי' אותיות עצמיי' הנ\"ל או אם ישפיע בריחוק יותר בערך מצד ערך ריחוק המקבל כו' יומשך באותיות המתפשטים מן העצמות כנ\"ל כאותיות השכל במדות ואותיות המדות במחשבה ואותיות המחשבה בדבור כו' ובריחוק יותר עד אותיות שנמשכים בהבדל והפסק מן הפה לאויר העולם שזהו האחרון מכולם וגם זה יותר קרוב מאותיות הכתב שלא נשאר שם רק רושם חיצוני אע\"פ שבא שם הכל בגלוי (וכמ\"ש במ\"א בראיה לזה מאובנתא דלבא שנשכח בפסק דין שנגמר בע\"ש כשכותבין אותו אחר שבת דלכך אין יושבין בע\"ש כו') ואמנ' בחי' אור ושפע שנמשך כמו ע\"י שערות וכמו התלבשות השכל במשל וכה\"ג הגם שהוא רחוק יותר גם מאותיות הכתב שבאותיות הכתב הכל בא בגלוי ואינו חיצוניות כ\"כ כחיצוניות החיות המצומצם שבשערות כו' מ\"מ יש בהן יתרון מעלה במה שאחוזים וקשורים בשרש יניקתם בפנימית ועצמות ומה גם שיוכל להיות בהם דוקא מצד המשכת שרשם יותר פנימית ועצמות מפנימית ועצמות שנמשך בהעלם באותיות הדבור מאותיות מחשב' ומדות עד פנימית הרצון וחכמה שיוכל לבא למקבל כו' וכמ\"ש במ\"א דהיינו משום שיצאו בבחי' מותרות זהו הוראה על היות שרשם מבחי' פנימית ועצמו' ביותר דזהו הכלל גדול בהשתלשלות דכל שהשפע הולך ממקום הגבוה במדרגה ביותר יותר יבא בצמצו' והעלם בדילוג הערך ביותר מצד ריחוק ערך המקבל אליו וכל שקרו' אליו ערך המקבל יותר יותר יומשך למקבל בקירוב הערך כו' ולפ\"ז השפע דשערות וכאותיות הכתב באים ממקום גבוה במדרגה ביותר מכל שפע הנמשך ע\"י אותיות עצמיים ואותיות המתפשטים הנ\"ל וד\"ל) והנמשל היוצא מכל הנ\"ל בחלוקי מדרגות שבבחי' אותיות שנק' ממוצעים לחבר העליון בתחתון כנ\"ל הנה בחי' אותיות שנבראו בהן העולמות שנמשך מאותיות הדבור העליון כי' מאמרות יהי אור ויהי רקיע הנ\"ל ה\"ז בחי' האחרונה שבדבור שהוא הבל הנפרד לאויר מהבל הפה העליון (ולכך דבר אלקינו יקום לעולם ואין כל חדש תחת השמש רק ברצון חדש כו' וכמ\"ש דברי אשר יצא מפי יצא ממש והיוצא מהווה כו') וזהו נק' הבלי' תתאין דמל' בעולמות בחי' ממוצע בין אותיות הדבור עצמן"],[1700400427,"לנבראים כו' והעליון מזה אותיות הדבור עצמן שמקבלין מהבל הלב כנ\"ל וגם בזה יש ממוצע בין אותיות עצמיים שבמדות הלב ובין אותיות הדבור ונק' קול הבל הלב קלא דלא משתמע בדבור וקלא דמשתמע הוא הנמשך בדבור ומשתמע לחוץ כנ\"ל והעליון גם מזה הוא אותיות גדולים הבלי' עלאי' דבינה שנק' אותיות השכל במדות וגם בזה יש ממוצע ע\"ד הנ\"ל באותיות המדות לדבור וכן משכל למחשבה או ממדות למחשבה כו' והעליון גם מזה הוא אותיות עצמיים שברצון שמתהווה השכל כמו והחכמה מאין כו' ויש בזה ב' מדריגות א' אותיות עצמיים שברצון שחוקקים לצורת השכל לזכות או לחוב כמו השוחד שיטה הרצון בעצם ויהווה שכל לזכות כו' ויש מדרגה ב' שבא מפנימית הרצון יותר ע\"כ יבא בדילוג הערך ובריחוק יותר כפי הכלל הנ\"ל והוא כמו ענין ובחי' השערות שהוא כדמיון אור השכל שמתעלם במשל כנ\"ל באריכות ויובן זה למעלה בדרך כלל בהפרש שבין השתלשלות העולמות מדבור ומדות וחכמה ורצון העליון הגם שיוכל לבא גם פנימית הרצון וענג בהבל חיצוני שבדבור כנ\"ל מ\"מ ע\"י בחי' אותיות הכתב ומכ\"ש בבחי' שערות הגם שבא שם האור ושפע בדילוג ובריחוק הערך יותר כנ\"ל אדרבה היא הנותנת שבאה השפע והאור ממקום גבוה ועליון מפנימית ועצמות המאציל ביותר שלזה לא יוכל לבא גם באותיות עצמיי' דרצון וחכמה ומדות וד\"ומ כו' רק בהעלם גדול דשערות או מעשה הכתב כו' והיינו ענין שרש התורה דאור תורה נאמ' בו עוטה אור כשלמה בבחי' לבוש וגם נק' משל הקדמוני שזהו דמיון לבחי' שערות כנ\"ל וכאשר נק' משל הקדמוני היינו למעלה גם מבחי' ירידת אור דתורה להיות בבחי' אותיות כמו מימינו אש דת כו' אש שחורה ע\"ג אש לבנה שנק' אותיות הכתב עכ\"פ וגם למעלה מאותיות החקיק' דחרות על הלוחות כו' וכן כשנק' בבחי' לבוש כמו עוטה אור כשלמה שכל זה ענין מקיף בלבד שלא בא האור רק דרך העלם ולא בגלוי כלל כהגבלה בכלים ואותיות אבל מעשה הכתב הוא גלוי ההעל' דמקיף וכך דרך בחי' שערות עכ\"פ יש קצת גלוי העלם המקיף רק שהוא בא בבחי' צמצום גדול ובהעלם יותר מאותיות הכתב כנ\"ל משא\"כ אותיות דרצון ושכל ומדות הנ\"ל באי' כסדר השתלשלות דאו\"פ בהגבלת כלים מעילה לעלול כנ\"ל וד\"ל:\n(לז) <b>ומעתה</b> הנה יש להבין בשרש ענין התהוות החכמה מלמעלה מן החכמ' שהוא מאין כו' כמ\"ש והחכמ' מאין כו' שהוא ע\"י מזל ונוצר כידוע שזהו כמו בחי' דילוג השפע שע\"י שערו' הנ\"ל ולכאורה יש להבין למה יש הפרש בין שפע אור הכתר לחכמה לשפע חו\"ב ומדות שמכתר לחכמה בא דרך דילוג הערך דהיינו העלם דמקיף הבא לגלוי בצמצום והעלם דשערה כו' כנ\"ל ולא דרך ע\"וע כמו מחכמ' לבינה ומבינה למדו' כו' (ולכאורה אנו מוצאי' שגם אור החכמה נאצלה ע\"י בחי' אותיות דוקא כמו ע\"י שם ע\"ב במילוי יודי\"ן ומבואר במ\"א דכמו שכלי החכמ' הוא בחי' שם ע\"ב כידוע בענין ד' שמות דע\"ב ס\"ג כו' כך בחי' שרש התהוות אור החכמ' נאצל ע\"י אותיות מעצמו' המאציל והוא ג\"כ ע\"י שם ע\"ב כו' וכן אור הכתר כו') אך הענין הוא להיו' שאור הכתר בכלל נק' בחי' מקיף והגם שנק' ממוצע בין עצמו' המאציל לנאצלי' הרי נק' בחי' גלגלת' כגלגלת עצם הראש שמקיף למוחי' שבו כו' וכל בחי' מקיף א\"א שיומשך ממנו אור ושפע למקבלי' בבחי' גלוי גמור כמו שהוא בע\"וע כו' אלא דוקא בדרך דילוג הערך כמו ע\"י בחי' שערות הנ\"ל וזהו ענין מזל ונוצר כו' אותיו' צינור כצינור דק שנובע בדקות והעלם וצמצום גדול וכמ\"ש במ\"א בענין הכל תלוי במזל אפי' ס\"ת בהיכל כו' וכמו מזל מחכים שזהו כח העלם השכל הנובע בהעלם לגלוי אור השכל הנק' סברא שלא נודע ונגלה מקור"],[1700400428,"זה הממציא השכלה גלויה זאת ואינו רק כמו צינור מעצם כח המשכיל ההיולי הפשוט הנק' ח\"ס בכלל והוא הנק' בחי' צומח שבח\"ס לבד והן כמו בחי' שערו' הנ\"ל והיינו ענין מזל ונוצר דא\"א כידוע דאבא יונק ממזל הח' כו') וכידוע בענין י\"ג ת\"ד דא\"א ששרם ממו\"ס בדרך דילוג הערך ולכך נק' מזלות לפי שהן יוצאים מבחי' מותרי מו\"ס דרך בחי' שערו' כו' וכל זה אינו אלא מטעם שהכתר הוא בחי' מקיף בכלל כעצם הגלגלת כו' כנ\"ל וכל מקיף א\"א שיבא למטה כ\"א בדרך דילוג הערך ולא בבחי' עו\"ע כנ\"ל וד\"ל (ובאמת עדיין אין זה מובן דלפי המבואר במ\"א בענין אורו' הנאצלים מעצמו' המאציל הכל שוין בזה שנאצלו ע\"י בחי' אותיות ושמות עכ\"פ כמו שם ע\"ב ס\"ג כו' ולכך נק' ע\"ס בכלל רזא דשמא קדישא שכולן אינן רק בבחי' שמות דעצמו' כו' כי מצד עצמו לאו מכל אינון מדו' כלל כידוע א\"כ למה מכתר לחכמ' בא דרך דילוג בבחי' שערו' כו' אך הענין ידוע שע\"ס דאצי' יש בהן ב' מדרגות א' כמו שנאצלו מעצמו' ולא זה מזה בהשתלשלות והב' כאשר באו בסדר השתלשלו' זא\"ז מכתר לחכמה כו' וביאור הדברים ידוע שבחי' עצם נקודת מציאותן הראשון לא נתהוו זה מזה רק הכל מן העצמו' כמו עד\"מ נקודת עצם החכמה לא נתהווה מכתר שנק' רצון שהרי יש מציאת שכל בלא רצון כלל אלא מעצם הנפש שנק' נפש השכלית כו' וכן החסד והדין לא נתהווה עיקר עצם מציאות נקודתן הראשונה כמו שהוא מתחלת הוייתן מן השכל שהרי יש מציא' אוי\"ר בלא שכל המוליד כלל וכלל כידוע ולכך שוין הכל בלי חילוק כלל לגבי העצמו' וכולן מקבלי' התהוותן רק מבחי' אותיו' ושמות העצמו' כנ\"ל וכמו עד\"מ מן התהוות הרצון מן הנפש ששוה עם התהוות עצם השכל והמדות מן הנפש כו' דהנפש עצמה מושללת מכל בחי' מציאת דבר מה כו' וכך ע\"ס נק' ע\"ס בלי מה כו' כידוע אך כ\"ז כמו שהע\"ס נאצלו מן העצמות אבל כמו שהן באי' בהשתלשלו' זה מזה ה\"ז עד\"מ באדם למטה כמו שמן הרצון נמשך שכל ומן השכל מדו' כידוע שכבר יש עיקר נקודת מציא' רצון ושכל ומדו' מן הנפש רק שבשעה שהנפש מתפעלת מתפעלת ברצון תחלה ומן הרצון יומשך טעם ושכל ומן השכל מדות כו' אזי יש חילוק מדרגות באופן הילוך השפע מזה לזה דמרצון לשכל בא דוקא דרך דילוג הערך כנ\"ל דא\"א שיתמשך גופו של רצון בשכל כי הרצון נבדל ערכו ממהו' שכל לגמרי כי אין טעם לרצון כלל כידוע והשפלתו וירידתו בשכל בא דרך העל' וצמצום להיותו בחי' מקיף כנ\"ל ואמנם משכל למדות בא דרך עו\"ע יש מיש אע\"פ שהשכל נבדל בערך ג\"כ מן המדות אבל יש מציאת מדות בשכל תחלה שזה נק' יש מיש משא\"כ ברצון לא יש מציאת שכל והטעם ושכל לרצון שיש בו בהעלם בא ע\"י בחי' צומח דהיינו מזל ונוצר כנ\"ל וזהו הנק' יש מאין כידוע) והנה מעתה יש להבין ענין כל אות שאין גויל מקיף לה מד' רוחות פסולה הנ\"ל בהיות ידוע בענין מזלות דא\"א שהן רק מבחי' מותרי מו\"ס שבגלגלתא ושרש צמיחתן מעצם הגלגלתא כנ\"ל וידוע שיש ב' מדרגות ארחין וחוורתי כו' ובחי' חוורתי דגלגלתא דא\"א הוא בחי' חסד דע\"י שמלובש בגלגלתא כו' וארחי' הוא מקום צמיחת שערות כו' והנה בחי' חוורתי הנ\"ל הוא בחי' מקור לצמיחת השערות הנק' ארחי' כידוע (וביאור הדברים ידוע שזהו בחינת העונג הפשוט הנעלם שממנו מקור נעלם ופשוט לרצון כי הרצון הוא בחי' המשכה עכ\"פ ומקורו הוא בעונג פשוט ועצמי והוא הנק' חסד דע\"י כו' וכה\"ג ובכלל נק' חוורתי דע\"י דבחי' לובן החסדים הטובים הפשוטים שכוללי' בהעלם כל מיני שפע רצון טוב לחסד וי\"ג חוורתי הן מקור י\"ג ת\"ד כידוע וגם הן מקור לתרי\"ג מצות ששרשם בתרי\"ג ארחי' דגלגלתא כידוע ומבואר במ\"א באריכות) והיינו כמו ענין הנ\"ל בקלף שכותבין עליו אותיות שהקלף הוא לובן פשוט ועצמי מקיף וסובל כל ציור והמשכת"],[1700400429,"הקוין הנמשכין בו בציור כל תמונת פרטי אותיות הנכתבים בו וכל אות מיוחד לו מקום בפ\"ע בקלף לבן זה ומוקף בד' רוחותיו מקלף לבן זה כו' וכך הוא למעלה בבחי' הארחין ושערות שהן כמו בחי' אותיות הנמשכי' כו' כך כל שערה המשכה מצומצמת שמיוחד לה מקום בבחי' חוורתי הנ\"ל שהוא כעצם הגלגלת כי עצם הגלגלת חלק והוא כמו דמיון קלף הלבן שסובל כל קוין וציור האותיות מקיף לכללותם יחד ומקיף לכאו\"א בפרט כך בחי' לבנוני' העליון מקיף לכל בחי' שערות הנמשכות משם וסובל הכל כאחד ומקיף לכאו\"א בפרט כי יש לכאו\"א גומא מיוחדת [וכמ\"ש בשערה בין כו'] וכך יובן בענין האותיות הנכתבים בד' פרשיות (כמבואר למעלה שב' ענינים הללו דאותיות הכתב ובחי' השערות הוא בחי' צמצום המשכות מבחי' המקיף דוקא שאין זה בע\"וע כו') דלכך כל אות שאין גויל מקיף לה מד' רוחו' שלה דוקא פסול' להיות שהגויל הוא קלף הלבן כמו בחי' מקיף דלובן העליון כו' ויש לכל אות ואות מקום מיוחד באופן שיהי' מוקף מבחי' לובן הקלף מד' רוחותיו דוקא שאז המשכתו בבחי' מקיף דוקא להיותו מוקף מכל ד' רוחותיו מלובן דקלף אבל כשנגע באות הסמוך לו אין לו הארת המקיף אליו מכל צד ופוסל הכל כו' וד\"ל) וכמו פ' קדש היא בבחי' אור ח\"ע דאצי' כנ\"ל כמו בנאצל בבחי' דילוג והעלם אותיו' בקלף המקיף כו' צריך לכל אות שבה גויל מפ' זו מקיף לה מכל ד' רוחותי' וא\"ל פסול וכך הוא בפ' והי' כ\"י שהוא בבחי' בינה שנז' בה יצ\"מ כנ\"ל וכמ\"כ בפ' שמע והי' א\"ש שהן בבחי' חו\"ג שהן ד' מוחי' דבחי' מקיפי' דחב\"ד דז\"א בתפילין שבראש כנ\"ל ובבחי' מקיפי' העיקר הוא הקלף של הפרשיו' שהוא כמו אור מקיף העליון דלובן העליון דהיינו שהוא אור פשוט שע\"ג נחקקו האותיו' שבפרשיו' שהן בחי' המוחי' והקלף מקיף כל המוחי' שבו כמו שהגלגלת מקיף למעלה כו' (וזהו בין בתש\"ר בין בתש\"י הגם שתש\"י הוא בבחי' מוחי' דנוק' שכלולי' בבית א' להיות' על יד שמאל כנגד הלב ומתאחד' בתש\"ר והיו לאחדי' כידוע]:\n[לח] <b>והנה</b> יש להבין מעתה בענין הרצועות דתליין על לבא שע\"ז א' שימני כחותם על לבך כנ\"ל וידוע דהרצועות כשרי' גם מן הקלף כו' רק שרצועו' שחורו' דוקא הל\"מ כו' והענין הוא להיו' כי שרש בחי' הרצועות שהן מעור הבתים המקיף לד' פרשיו' כו' הרי בהכרח שגם הרצועות בבחי' מקיף דד' מוחי' שבפרשיו' ולכך תליין על לבא דוקא בבחי' מקיף כנ\"ל ולהבין זה הנה יש להקדים תחלה ענין המאמ' דס\"י בג' דברי' כו' בספר וסופר וספור כו' וידוע דספר הוא בבחי' בינה שנק' פתוחי חותם כידוע והענין הוא דשרש בחי' התהוות האותיו' הוא בבינה דוקא והיינו כאשר נבקע בחי' יסוד אימא כו' שזהו הנק' פתוחי חותם כו' וביאור הדברי' ידוע שבחי' יסוד אימא הוא בחי' ההתקשרו' במושכל היטב לעומק דהנה זהו כלי קליטת המושכל שקולט השג' המושכל נק' יסוד אימא ויש בזה ב' מדרגו' הא' כאשר הוא סתום שאז אין בו בחי' אותיו' עדיין ולא מקור לאותיו' מצד סתומתו בהעלם עדיין כו' וכמו שאנו רואי' בחוש שכאשר אדם טרוד ביותר באיזה מושכל עמוק להיות שכלי קליטת השכל קשור ומוטרד ביותר באור שכל זה עדיין אין שם בחי' אותיות כלל רק עיון וסקירה הנק' מחשבה עיונית שאינה בבחי' אותיות כלל רק בחי' מחשבת שכל ומה שחושב ומעיין בשכל בא דרך סקירה בבת א' ולא בבחי' התחלקות אותיות במחשבה זו כלל (וכשיטרד יותר דהיינו שעדיין אינו מושג לו השכל ורוצה להשיגו שעדיין אין השכל בא בבחי' מחשבה הנק' מחשבה עיונית כנראה בחוש שתשתומם מחשבתו כרגע עד שיבא להשיג השכל אז נק' עיון מחשבה עכ\"פ וזהו סתימת יסוד אימא בהעל' מצד קוצר המשיג ועומק המושג ועי\"ז דוקא נבקע יסוד זה שהוא מה שבא לכלל השגה כו') אך אחר שנבקע בחי' יסוד אימא"],[1700400430,"הנ\"ל הוא עוצם התקשרו' כלי' הקליט' במושכל כאשר יבקע מצד שנתרבה בו אור ירידת השפע לבא מהעלם שלו ולא יכול עוד להצפינו בהעלם וסתימות כו' אזי יתהווה אותיו' במחשבה זו והוא בחי' התחלקו' גלוי אור המושכל בחלקים דהיינו בהתחלקו' אותיו' המחשבה שמיד שנבקע בחי' יסוד אימא הנק' חותם בא בחי' התחלקו' אותיות במחשבה והוא בחי' ה\"ג מנצפ\"ך דאימא שמחלק אותיות המחשבה כידוע והנה מסיבת בחי' הבקיעה דיסוד אימא נחלק אור השכל להיות בבחי ד' מוחין שהן ד' פרשיות דתפילין כידוע וכנרא' בחוש שהטיי' עצם השכל להטות כלפי חו\"ג ע\"י הדעת נוטה כידוע אין זה אלא כאשר מתהוו' אותיו' השכל במחשבת שכל הנ\"ל וטרם שבא לכלל אותיות רק הוא נסקר בעיון כו' אין שם גם בחי' התחלקו' השכל לחו\"ג שלא ידע איך יפול דבר המשפט של השכל אם לזכות או לחוב כו' וכמ\"ש במ\"א וד\"ל וזהו שרש ענין ד' פ' דתפילין שנק' ספר שבא מבחי' אותיות דבינה שנמשך לחו\"ג כו' והן שמע והי' א\"ש ולכך כל הד' פ' כתובים באותיות ע\"ג הקלף שנק' ספר מטעם הנ\"ל אך הנה שרש הרצועות אע\"פ שהן מעור פשוט יש בהן יתרון מעלה מד' פ' שהן ד' מוחי' לפי שהרצועו' נעשי' מעור הבתים המקיף לד' פ' שהוא למעלה מבחי' אותיות (וגם למעלה מן הקלף וגויל דנק' מקיף לאותיות עכ\"פ ועור הבתים מקיף כללי כגלגלת המקפת כללו' המוחין שבד' חדרים כו') וזהו טעם שהרצועות תליין על לבא מבחי' מקיף על הלב דלב מקבל מל\"ב חדרי' שבמוח לבד כידוע ואמנם הרצועות נמשכים מתש\"ר מעור הבתים שלמעלה מעלה מבחי' המוחי' דד' פ' כנ\"ל וז\"ש כחותם על לבך שזהו רצועות דתש\"ר דתליין על לבא דוקא כנ\"ל וד\"ל ולהבין זה בתוס' ביאור הנה יש להקדים מאמר בידוע באד\"ר דז\"א בע\"י עצמו אחיד ותליא (פי' למעלה מחו\"ב שהן מקבלין מב' מזלו' ונוצר ונקה שאינן רק חיצוניו' ע\"י שמצומצם ברצון הנמשך לשכל שנק' ונוצר אבל המדו' שרשם בפנימי' ע\"י כמשי\"ת) דהנה לכאורה אנו רואים שעיקר ומקור חיות המדות הוא נמשך מבחי' האותיו' דמח' דבינה שמתפשטת במדו' להחיותם ע\"י הדעת המתפשט (דדעת גניז בפומא דאימא כמ\"ש כי כו' מפיו דעת ותבונה כמ\"ש במ\"א ומ\"ש במ\"א דדעת גניז בפומא דמלכא היינו הך דבינה נק' מלך כו') בהיות שאנו רואי' מופת לזה מגידול המדו' שתלוי בגידול השכל דוקא דלפי שכלו יהולל איש כידוע דהקטן ששכלו קטן מדותיו קטני' וכשיגדל בערך השכל כך ממש יגדלו ערך מדותיו להיות שהמדו' נולדי' רק מן השכל וכאשר שכלו גדול להשכיל עניני' גדולים כממון וכבוד וכה\"ג כך יולדו המדו' בבחי' גדלות הערך לאהוב הכבוד והממון וכה\"ג כי מתאחדי' כא' ממש שהרי מיד שיעלה במוחו הבנת טוב ענין הדבר מיד יאהוב בלבו לאותו הדבר והקטן להיותו קצר השכל להשיג טוב דבר החשוב ממילא אין בלבו אהבה לזה ולא יתפעל ממנו כלל וכשיגדל וישיג טוב הדבר החשוב לפי ערך טוב השגתו בשכלו כך יתפעל בלב אליו כידוע ונמצא שהשכל והמדו' כמהו' א' הוא וראי' שגם התינוק לפי קוצר השגתו בדברי' קטני' פחותי הערך כך יולד בלבו התפעלות אליהם לפי שהמדו' נגררי' בגידולם אחר גידול המוחי' כמו שיגדל העלה עם הפרי וכמו העץ וקליפתו כו' וכמ\"ש במ\"א בענין כי האדם עץ השדה כו' ומכ\"ז מובן דעצם מציא' המדו' עיקר התהוותם בעצם וגידולם הוא בא רק לפי ערך התהוות וגידול השכל תחלה כו' ואם לא מציאת השכל אין מציאות מדות כלל וכלל ולפ\"ז משמע דעיקר התהוות עצם מציאו' המדות נתהוו רק מן השכל ובאמת יש סתיר' גדולה לזה שאנו רואי' שיש למציאו' המדות בלא שכל כלל שהרי מדו' הנולדי' באדם בתולדתו בטבעיות כמו למאוס ברע ולבחור בטוב ודאי מציאות המדו' הללו ישנם בטבע בלא שכל וטעם המוליד כלל כי גם אם לא יתבונן ברע המזיק לו כאש ונחש ולסטי' שונא"],[1700400431,"בטבע לרע זה ומואס ובורח ממנו רק שע\"י ההתבוננו' יותר יברח כי גם התינוק ובהמה יברחו מן האש כמו הגדול בשכל ממש רק שהגודל בשכל ודעת יבחין יותר איכות ומהות הרע המזיק יתפעל יותר וכן באהבת דבר הטוב ונחמד מדה זו יש בטבע הבריאה ובאדם ביותר גם בקטן כמו בגדול לאהוב ולחמוד דבר הטוב ולרוץ אחריו כמאכל ולבוש טוב ודבר שבממון וכבוד ושאר תענוגי עוה\"ז רק שהשכל המתבונן בטובו ביותר יתפעל יותר כו' ונמצא מואס ברע ובוחר בטוב שיש בכלל בכל טבע בריאה אינו נמשך מצד הדעת עיקר תחלת מציאותו רק נולד כך בטבע והדעת והשכל הוא רק כמורה ומבחין יותר לטו\"ר ולהורות ולהבחין בטו\"ר ואין זה רק כמו שהאור הנר יגלה והבחנה טובה ביותר בין אוצר טוב שבדרך ללסטים ומזיק רע או בור גם שהשכל מבחין יותר אין זה בעצם מהות הדבר שזה א\"צ שכל וטעם כלל רק להורות ולהבחין מי הוא הטוב ומי הרע כו' וכשבא להבחנה זו מטבע הבריאה למאוס ברע כו' וא\"כ אין השכל רק כמו האור שמגלה הדרך ילך בה שלא יפול בבור כו' וכך בעסק דבר מה לילך בהשכל שלא יפול ברע כו' ולכך החכמה נק' אור שמאיר למדות איך לבחור בטוב כו' אבל עצם מציאת המדו' למאוס ברע כו' לא נתהווה מן השכל כלל אלא הן בטבע תולדה מבטן כו' וד\"ל אך מזה עדיין אין ראיה למדות שנולדים רק מצד השכל והרי המופת הנ\"ל מה שתינוק יאהוב דברים קטנים מצד שכלו מטה לאהוב דבר קטן כו' כנ\"ל זהו גם במדות טבעיו' הרי גם הטבע דמדות משתנים עפ\"י השכל עכ\"פ כשהשכל גדל כו' [כי גם השכל טבעי כמו המדות שבשכל לטו\"ר טבעי הוא יש חכמים להרע מצד טבע שכלם ולהטיב לא ידעו כלל כו' וכן יש שכל מתפעל כך ויש כך כו'] ובאמת גידול השכל וגידול המדות שבאי' כא' כנ\"ל היינו רק מדות שבשכל דכאשר עצם השכל מתרחב במוח ממילא מתרחב מדות שבשכל לדברים גדולים יותר ואז ממילא מדות שבלב הוא שמתפעלים לדברים גדולים ובתינוק מדות שבשכלו לדברים קטנים כמו לשחוק והוללו' כו' כי עד יג\"ש הגידול רק במדות לבד כו' (ואמנם טבע מדות שבשכל לטו\"ר משתנה ג\"כ בגידול השנים ובסיבה זאת משתנה טבעי המדות לטו\"ר שנולדו מבטן כו' דלפי שכלו יהולל כו') אך הנה אנו רואים מופת גמור גם במדות שנולדו רק מן השכל ואם לא השכל וההתבוננות לא היה מתפעל כלל שגם שם יש מציאות המדות בעצם שאינם מתהווים מן השכל אלא אדרבה גדול כחם הרבה מכח השכל עד שלא יוכל השכל למשול בם להפוך אותם כהורא' השכל כו' דהנה אנו רואים במתפעל מן השכל דוקא אם לא היה ערך גידול המדה רק לפי ערך גידול השכל ולא יותר אפי' כקש\"י א\"כ ודאי לא תמצא מציאת התפעלות המדה יותר מהתפעלות השכל ולמה אנו רואים בחוש שכאשר יתפעל אדם בלב באהבה לדב' מה מצד שהתבונ' בשכלו ונתפעל בשכלו תחל' שמז' הוליד התפעלו' הלב ויוכל להיות שתתגבר התפעלו' הלב ביותר מכפי המד' שבשכל דהיינו שנתגבר התשוקה וחמדה בלב נפלאה ורבה ועזה ביותר שלא היה במוח ערך בזה התפעלו' השכל כלל עד שיכול להיות שגם אם יטה שכלו אח\"כ בהיפוך מהתפעלו' זאת שבלב לא יכול המוח לשלוט על הלב ולא יעצור רוחו בשו' אופן ע\"ד דוגמ' כשמתפעל במו' בטוב המו\"מ או הבנין וכה\"ג ויולד מזה התפעלו' בלב אז תתגבר התפעלו' הלב בלא טעם ושכל רק טבעיו' כבהמה עד שגם אם יגזור השכל היפוכו שלא טוב הדבר כלל וכלל לא יוכל להפוך לבבו כלל ואם היה עיקר תחלת התהוות מציא' ההתפעלו' בלב רק מהשכל איך יהיה כח הנולד גדול מכח המוליד ולא עוד אלא שיעש' היפוכו ממש כו' אין זה רק שבהכרח לומר שיש למציא' מדו' בעצם תחלת התהוותם למעלה מעלה מן השכל אלא שהשכל מורה למדו' אופן ואיכות ההתפעלו' לטו\"ר כך ולא כך כמו"],[1700400432,"לאהוב דבר זה מצד טובו שנתברר לו בשכל כו' ולמאוס ולשנוא דבר זולתו מצד שמאסו הבחנת השכל כו' אבל עצם המדו' לטו\"ר טבעיי' הם מבטן כו' כנ\"ל ע\"כ גם אם כלה כח המוליד' שהוא השכל הרי טבע עצמותם גובר על הוראת השכל ולזאת גם אם השכל יורה להיפך אח\"כ לא יועיל כי כח עצמותם הגבה למעלה ממדו' שבשכל כו' וזהו הסיב' שתתפשט התפעלו' המד' יות' ממדו' שבשכל כנ\"ל [וכמו שאנו רואים באו\"נ איש לרעהו מצד הטובות וחסדים שעשו זע\"ז כשירחקו זמן רב ויתראו פנים תגדל האהבה ושמחה ביתר מכפי ערך השכל וטעם לאהבתם כו'] ומכ\"ז הוראה עכ\"פ שמדות טבעיים שרשם למעלה גם ממדות שבשכל שהרי גידול מדו' שבשכל שעושה גידול מדות שבלב אין זה גורע ולא מוסיף כלל במדות טבעיי' ועצמיי' כי כלל גדול הוא דטבע המדות העצמיים שרשם ברצון ועונג העצמי שלמעלה מרצון שמצומצם בשכל וטעם כמשי\"ת ע\"כ גם טבע המדות שבשכל אין להם ערך לטבע המדות שבלב רק שגידולם באים כא' והשרש לכל הוא מה שיש יתרון לשרש המדות שבלב בעצמות טבע המדות שברצון שלמעלה ג\"כ ממדו' שבשכל וטעם לרצון כמשי\"ת וד\"ל:\n[לט] <b>והנה</b> עפ\"י כל הנ\"ל יובן ענין המאמר דלעיל דז\"א בע\"י אחיד ותליא כו' אך יש להקדים עוד ענין א' והוא בענין ובחי' ח\"ס דא\"א שזהו ענין טעם כמוס לרצון כידוע בזהר בכמה דוכתי דאית רצון ואית רצון כו' דהיינו רצון פשוט ורצון מורכב רצון פשוט היינו שלמעלה גם מטע' כמו' לרצון והו' נק' עצם הרצון שאין טע' לרצון כלל ורצון מורכב בשכל וטעם כמוס כו' (וכן בעונג שברצון כידוע) והנה ידוע דעצם הרצון נק' כתר שבכתר והוא למטה באדם בחי' יחידה ונחלק גם הוא למדות חו\"ג אך הן עצמיי' ממש כטבע הטוב בעצם להיות לו רצון תמיד למעלה מן הטעם לגמרי ומה שיתפעל ברצון מורכב בשכל וטעם כו' הכל מצד טבעו הטוב בעצם הוא בא וכן להיפך כו' ומבחי' מדות שבעצם הרצון והעונג משם נמשך טבע המדות בתולדותם שזהו למעלה ממדות שברצון המורכב בשכל וטעם ולכך הגם שלפי שכלו יהולל כו' דגידול מדו' הטבעיי' בא עם גידול השכל שהן מדות שבשכל וטעם לרצון הנ\"ל אבל עצם מהותם נתהווה בעצם הרצון ששם המדו' עצמיי' עד שגם מדו' שבשכל בטבעם להטיב ולהרע כנ\"ל הרי נמך שרשם העצמי ממדות העצמיי' שבבחי' יחידה כטבע הטוב בעצם ששכלו בטבעו מטה כלפי טוב כו' ובזה יובן הכל גם מה שמשתנ' טבעי המדות עפ\"י שינוי טבעי מדות שבשכל בגדולתו אין זה שינוי בעצם מהותם כלל שהרי גם זקן שקנה חכמ' אין שינוי כלל בעצם טבעי רצונותיו לחו\"ג כמו שנולד כו' ומה שמדותיו שבחכמתו נשתנה במה שנתגדלו בגדלות השכל אין זה שינוי בעצם המדות כלל דהיינו כמו מי ששכלו מטה כלפי חסד מצד גדלות השכל היפך טבעו במדות שביחידה אין זה שינוי כלל בעצם טבעי מדות דיחידה כלל וד\"ל (וז\"ש דוד ואני בהמות כו' בהמה רבה שלמעלה משכל היותר עליון שבא להיות טעם לרצון כו' וכמ\"ש במ\"א) ובכל זה יובן טעם התגברו' המדו' מכח עצמם הגם שנולדו מן השכל שיוכל להיו' יותר מכפי ערך כח השכל שמולידם כנ\"ל לפי ששרש ומקור הראשון של התהוות עצם מהו' המדה הוא בעצם הרצון ועונג שלמעלה לגמרי מן השכל אלא שעוברי' דרך השכל דרך מעבר בלבד דהיינו מה שלא יתפעל אדם בלבו אם לא שחייבו השכל תחלה בין לחסד בין לדין וכמו שגדולן כא' כנ\"ל הרי זהו רק דרך מעב' לבד אבל עיק' מהו' המדה באה מן עצם הרצון והעונג שלמעלה מטעם ושכל לרצון כו' שהוא הנק' רצון ועונג פשוט כנ\"ל וד\"ל ועם כל זה יובן הנמשל למעלה בבחי' ז\"א דאצי' שהן בחי' ו\"ק הנולדי' מן השכל שהוא בחי' בינה כנ\"ל בענין אותיו' השכל במדו' שזהו חיותם וקיומם ולכאורה שרשם הראשון"],[1700400433,"הוא בבחי' מזלות ונוצר ונקה שהן שרשי המוחי' דחו\"ב המולידי' המדות כידוע והמזלות הללו הן רק במדו' שברצון מורכב בשכל וטעם כמוס שנק' ח\"ס דא\"א כידוע דשרש החכמה מחסד דא\"א בקו הימין כו' ושרש הבינה מגבורה כו' ולמעלה מזה הוא מזל ונוצר ונקה שמבחי' ח\"ס עצמו כידוע ומבואר במ\"א אך הנה כ\"ז אינו רק דרך מעבר בלבד ששפע הח\"ס מאיר למדו' שברצון ומשם לחו\"ב דאצי' וחו\"ב מולידי' המדו' כו' אבל עיקר שרש הראשון למדו' דאצי' הוא בבחי' פנימי' ע\"י וא\"א שלמעלה מח\"ס כו' והוא בבחי' עצמיי' שברצון ועונג הפשוט כנ\"ל וזהו שא' דז\"א בע\"י אחיד כו' דז\"א אחיד ותליא בשרשו הראשון בהעל' העצמו' של המדו' דע\"י וא\"א שלמעלה משרש חו\"ב דאצי' רק בבחי' גלוי עובר דרך חו\"ב כו' וד\"ל (ולפ\"ז לא יובן מ\"ש ויוציאנו ה' כו' ביד חזקה ובזרוע כו' שהן בחי' חו\"ג דא\"א כמבואר בפע\"ח בענין בצאת ישראל ממצרים ובענין עבדי' היינו אנו בני ז\"א כו' דאם שרש ז\"א בע\"י עצמו שלמעלה מזרועות דא\"א שנק' יד הגדולה ויד החזקה כידוע וכן מ\"ש במ\"א בענין המא' דרישא דמלכא בחו\"ג אתתקן שזהו בחו\"ג דא\"א לבד כו' אך מכ\"ז אין סתירה כלל דלכאורה לפי הנ\"ל ביותר יקשה המא' הידוע במה תצעק אלי שהוא ז\"א בע\"י תליא כו' דאם שרש מהו' ז\"א בע\"י עצמו מהו שא' בעתיקא תליא הלא גם ז\"א עצמו בע\"י אחיד ותליא כו' אלא צריך לומר שיש הפרש בכל זה בין בחי' המוחי' לבחי' המדות עצמם דמדו' דז\"א שרשם במדו' העצמיי' שבפנימי' ע\"י וא\"א שלמעלה מחו\"ב דא\"א וע\"י כו' כנ\"ל אבל בחי' המוחים שבמדו' דז\"א הן מקבלי' מחו\"ב שהוא מוחי' דאו\"א והן מקבלים ממדות דא\"א ששרשם בחו\"ב דא\"א וע\"י כו' והיינו רישא דמלכא בחי' חב\"ד דז\"א בחו\"ג דא\"א אתתקן כו' וכמ\"כ חו\"ג דא\"א שנק' יד הגדולה כו' לפי שבחי' המוחי' דמדות שהוא שכל וטעם שבמדה שרשה במדו' שבשכל עד מדו' שבשכל וטעם כמוס לרצון הנק' ס\"ס שמשם שרש הראשון בטעם לחוב או לזכות שכל זה אינו רק בחי' רצון מורכב לחו\"ג עפ\"י טעם כמוס לרצון כנ\"ל וז\"ש דרישא דמלכא דוקא בחו\"ג דא\"א שמקבלי' מח\"ס אתתקן דפי' תיקון הוא המשכת בחי' מוחין חדשי' לאו\"א ומשם לז\"א בחי' מוחי' חדשי' כו' וכה\"ג ענין ובחי' לידת ז\"א בבחי' מוחי' למדו' שנק' מוחי' דיניק' כו' והוא ע\"י יד חזקה וזרוע נטויה דא\"א שהוציאו ממיצר העורף דפרעה כו' כידוע אבל בחי' המדו' עצמם שרשם למעלה מח\"ס שברצון והוא בעצם הרצון והעונג הפשוט שבלתי מתלבש בשום שכל וטעם כלל כנ\"ל זהו למעלה משרש המוחים דמדות שאינו רק במזלות או זרועות דא\"א כנ\"ל ובזה יתורץ גם ענין המא' דמה תצעק אלי הנ\"ל בהיו' ידוע בענין ה' איש מלחמה כו' כמארז\"ל דבים נדמה כבחור עושה מלחמה כו' ובמ?ת נדמה כזקן במלחמתה של תורה כו' להיו' שטענה מדה\"ד מה נשתנו אלו מאלו כו' ולא הי' כח במוחי' שבמדו' עליונו' דז\"א להציל' ממה\"ד אך כתי' תפאר' בחורי' כחם העצמי שבמדו' עצמיי' והיינו שבמלחמ' נצח למדה\"ד דכח זה אינו בא מצד המוחי' שבמדו' שהרי גברה חיוב מדה\"ד באמ' מה נשתנו כו' וגם בשרש הראשון למוחי' שבמדו' שהוא מוחי' עליוני' דא\"א במדו' שברצון כנ\"ל גם שם לא נמצא מקור מוצא לזכות להטות הרצון לטוב לישראל ולדין למצרים אך ורק מצד עצם כח המדו' כמו שהן בשרשם למעלה מטעם לרצון אלא ברצון עצמי ופשוט הנ\"ל ששם דוקא עלו ישראל להיות בבחי' חסד וטוב בלא טעם כלל כמ\"ש אך טוב לישראל כו' למעלה מן הטעם לגמרי רק בבחי' עצמיות וטבעיות כו' כידוע בענין ישראל עלו במחשבה פי' עלה בעצם הרצון הנק' מחשבה סתימאה והוא עתיקא דעתיקין או עתיקא סיתימאה בחינת כתר שבכתר כנ\"ל) ומחמת זה דוקא נמצא כח מלחמתה של תורה במתן תורה"],[1700400434,"שנדמה כזקן כו' משום דבחי' המוחי' שבמדות דתורה ג\"כ נמשך שרשם מעצמו' החכמה הקדומה שבעצמו' הרצון ממש ואע\"פ שנק' חש\"מ עכ\"ז חכמתו העצמי' היא וכמ\"ש ואהיה אצלו אצלו ממש ואע\"פ שהמדות שמסתעפים מן החכמה למטה ממדות העצמיים היינו בבחי' גלוי רצון ושפע למטה אבל בעצמות אא\"ס ממש הוא ורצונו וחכמתו ומדותיו הכל א' בבחי' עצמיות ממש ואין לחלק ביניהן ולפ\"ז מה שנא' ה' איש מלחמה בים להכריע בהצלת ישראל מצד כח טבעי המדות הכל א' עם מלחמתה של תורה כשנדמה כזקן שקנה חכמה ממקורה שגם זה למעלה מבחי' ח\"ס הנ\"ל מטעם הנ\"ל (וז\"ש תפארת בחורים כחם הוא שעושה הדר זקנים שקנה חכמה (ומה שבסנהדרין היו זקנים דוקא כי סבא דעתיה סתים ולא יתערב בשכל מטבעי המדות לחו\"ג כלל וכלל היינו במשפט התורה שירדה למטה לברר לעה\"ד טו\"ר שבמדות שלמטה מן החכמה יש תערובות טו\"ר כו' משא\"כ במדו' עצמיים שלמעלה מן החכמה שהוא מקור אמתי לח\"ס להטות הרצון לחו\"ג כו' כנ\"ל וז\"ש מה תצעק אלי שהוא בחי' ז\"א מדות שלמטה מן החכמה שאין בכחם מצד צמצום המוחים שבהם להכריע לזכות גם בשרש המוחים בח\"ס כנ\"ל ולא מצד עצמם כשהן למטה מלובשים במשפט התורה לברר לעה\"ד כו' אלא בעתיקא עצמו תליא ששם כח המדות העצמיי' למעלה מטעם וחכמה ומשם עיקר כח עצם המדות שלמטה מן החכמה ולא יצאו דרך החכמה רק דרך מעבר כנ\"ל והכוונה כך היא מה תצעק אלי בהיות המדות מקבלי' מחו\"ב בע\"י תליא ושם שרש עצם המדות ושם אני דוקא ילח' לכם וכמ\"ש ה' ילחם מטע' הנ\"ל וד\"ל)\n[מם] והנה אחר כל הנ\"ל יובן ג\"כ שרש ענין הרצועו' דתליין על לבא הנ\"ל דהנה מבוא' למעל' בשרש עור הרצועות שהן מעור הבתים שלמעלה מעלה מבחי' הד' מוחי' שבד' פרשיות דתפילין דהיינו מבחי' המקיף דכתר שנק' ע\"י וע\"כ הרצועות תליין על לבא בבחי' מקיף למדו' שבלב כי א\"א שיבאו להאי' במדו' בבחי' או\"פ כי המדות שבלב מקבלים מחו\"ב שלכך נק' לב ע\"ש ל\"ב נ\"ח שבל\"ב חדרים שבד' מוחין כידוע ושרש הרצועות מבחי' מקיף דבתים כנ\"ל ולכך תליין על לבא בבחי' מקיף למדו' שזהו ענין בחי' המדות כמו שהן בשרשן הראשון בעצם והוא ברצון ותענוג הפשוט (שלמעל' גם מח\"ס דא\"א המקור למדות שברצון ע\"י ב' מזלות כנ\"ל שזהו פי' המאמר דלעיל דז\"א בע\"י עצמו אחיד כו' בבחי' פנימית ע\"י שנקרא כתר שבכתר בכלל אך להיות הרצועות נמשכין מן הבתים לימין ושמאל כו' והוא מצד שרש במדות שברצון הפשוט שמקיף למוחים שבד' פ' כו' ע\"כ הרצועו' בחי' מקיף למדות דוקא וזהו הטעם דתלייא על לבא שע\"ז א' שימני כחותם על לבך כנ\"ל (דכמו שהבתים מקיף כללי לכללות הד' מוחים שבד' פ' ששם נראה לל\"ב חדרים כו' כך הרצועות מקיפים למדות שבלב שמקבלים מן המוחי' בבחי' או\"פ) [וכמ\"ש במ\"א בענין מצנפת מקיף דראש ואבנט מקיף דלב הרי האבנט ל\"ב אמ' כפלים כמצנפת כו] אך מעתה לכאורה אינו מובן הטעם ברצועות שיהיו שחורות דוקא והל\"מ הוא כמארז\"ל רצועות שחורות הל\"מ כידוע וגם עור הבתים מבואר בפוסקים שצ\"ל שחורות דוקא וזה פלא גדול לפי הנ\"ל דשרש הבתים והרצועות הן בבחי' מקיף דמוחים ומדות כו' ועוד יותר יפלא דאם אפשר לומר בתירוץ הקושיא הזאת משום דכל בחי' מקיף הוא בהעלם דוקא וכמו ישת חשך סתרו ושחור מראה עמוקה היא בהעלם וחשך היפך האור שהוא בגלוי הו' אך א\"כ למה בהיפוך הוא בגויל שבפרשי' דכל אות שאין גויל מקיף כו' כמבואר למעלה שהגויל הוא בבחי' מקיף של האותיות"],[1700400435,"ולמה הגויל לבן דוקא ואם מקיף דכללות המוחין שבד' פ' כעור הבתים שחור הוא ומקיף דמוחין שבאותיות בפרטות הוא במראת לבן וידוע דהלובן מורה על בחי' חוורתי דע\"י שהוא מקיף עליון יותר כו' אך הנה התירוץ האמיתי לב' הקושיות דלעיל הוא ענין הידוע בבחי' מקיף שיש בו ב' מדרגות א' התלבשותו בבחי' חיצוניות בלבד כמו שערות הראש וכעצם הגלגלת דאע\"פ שהגלגלתא בחי מקיף על המוחין מ\"מ חיצוניות המקיף הוא כי אינו אלא עצם דומם בעלמא כו' רק שחיצוניות שבעליון מקיף לתתחון שהן המוחין שבו אבל מ\"מ המוחין הן פנימיי' יותר אע\"פ שהן למטה מן הרצון שבגלגלתא (וכמ\"ש במ\"א בטעם מה שלפעמי' משמע דתורה למעל' מן המצות כו' וכמ\"ש והחכמה תחי' בעליה בעלי' דחכמה כו') והב' בחי' הארת המקיף כמו שהוא בבחי' הפנימי' שבו והוא ההפרש שבין מראה לבן ומראה שחור דכאשר בא הארת המקיף בהתלבשות חיצוניות בא בגוון שחור (וכמו ישת חשך סתרו וכמו ומשה נגש אל הערפל כו' וכמו הנני בא אליך בעב הענן וכה\"ג בסכך דסכה כו' שמתעלם ובא בהעלם בלבד כו') אבל כאשר בא אור המקיף בבחי' פנימית ועצמות שבו כמו שהוא בא בגוון לבן דוקא וכמו לבושיה כתלג חוור כו' וכמו עוטה אור כשלמה אור המאיר ומבהיק בבחי' לובן כו' (ובתורה מאמר מימינו אש דת כו' אש שחורה ע\"ג אש לבנה שהן ב' מיני מקיפי' הנ\"ל והוא מצד ששרש התורה בעה\"ח כמ\"ש עוטה אור כו' אור לבן וגם באה בעה\"ד טו\"ר לברר במדות שבה טמא טהור כו' והוא אש שחורה כידוע באש דהר סיני כו' וד\"ל) והנה גם בכאן בענין הבתים והרצועות הגם שהם בבחי' מקיף כנ\"ל אבל הרי הוא בחי' התלבשו' וירידת המקיף בחצוניות בלבד שהרי הבתים הן כמו כלי' חיצוניי' לפרשיות המונחים בהן ע\"כ מראה הבתים שחור מטעם הנ\"ל דכל בחי' מקיף בירידתו למטה לבא בהתלבשות בחיצוניו' הוא בא במראה שחור (וכמו במרכבת יחזקאל סוסי' שחורים דקאי בזמן הגלות דמלובש שם בהעלם וכן שחורה אני ונאוה בגלות דוקא וכה\"ג אך זה סותר לכאורה ענין וראו כל ע\"ה כי שם ה' נקרא עליך שזהו תש\"ר שהן מגולין דוקא וכמו לע\"ל דכתיב ולא יכנף עוד כו' שזהו כמו אור בלא כלי ומראה השחור דבתים היפך זה לכאורה ובאמת אדרבה מזה מוכח דמקיף דתפילין בא בירידה והתלבשות למטה דוקא בחיצוניות שהרי א' וראו כל ע\"ה דגם ע\"ה יראו אות המקיף דתפילין שזהו תש\"ר דוקא ולא תש\"י שצריך להיות מכוסה ולא מגולה כמ\"ש לך לאות ולא לאחרים לאות כידוע ע\"כ צריך להיות הבתים שחורות וכו' ומה שאמרז\"ל ע\"פ וראית את אחורי מלמד שהרא' לו קשר של תפילין ש\"ר שמאחוריו דמשמע דמ\"ש ופני לא כו' קאי בתש\"ר כו' ודאי כמו שיהיה לע\"ל דלא יכנף עוד כו' וגם תפילין דמארי עלמא שהקב\"ה מניח נק' פאר שהוא מקיף העליון כמו שהוא בבחי' פנימי' דוקא וראיה ממקום התפילין בראשו של כה\"ג שהוא בדוגמא העליונה ממש שהי' בין ציץ למצנפת כמו ב' אצבעות מקום שמוחו של תינוק כו' וציץ שעל מצחו לרצון תמיד כו' ודאי בחי' מקיף דפנימי' הרצון והעונג הפשוט כו' ותפילין בא בק\"ו מציץ לענין היסח הדעת כידוע וד\"ל) אבל הנה בחי' המקיף שבא כמו שהוא בבחי' הפנימי' ע\"כ מראהו לבן כנ\"ל והיינו לפי שבבחי' אותיות דפרשיות כמו קדש והיה כ\"י כו' הן בבחי' פנימית המוחי' שאע\"פ שהן למטה מן הגלגלתא כנ\"ל מ\"מ הן בבחי' פנימי' ביותר ולפ\"ז בחי' מקיף שלהן שהוא הגויל הוא מקיף העליון שהוא בבחי' הפנימי' כמו שנוא שאינו בא דרך ירידה והתלבשו' בחיצוניו' אע\"פ שהוא מקיף למוחי' בלבד (ועיקר כענין לפי שהמקיף דאותיו' עצמן הוא בבחי' מקיף דכתר כי"],[1700400436,"כל אות בפ\"ע שרשה בבחי' עצם אור הכתר כידוע וגויל המקיף לה הוא עצם אור הכתר והוא למעלה ממקיף דמוחי' שבפרשיו' כבתים וכה\"ג לכך הגויל לבן) ועוד יש טעם בזה לפי שהמקיף דרצועות הוא רק מקיף על המדו' שבלב כמ\"ש דתליין על לבא והמדו' מקבלי' מן השכל אע\"פ ששרשם במדו' שבכתר כנ\"ל מ\"מ בירידת המקיף במדו' שלמטה מן השכל להיו' בחי' מקיף עליהם צריך שיתעלם האור ויתלבש ג\"כ בלבוש שחור וגם מדו' שבע\"י אין ערוך לבחי' עצמו' אור הכתר כמו שהוא למעלה מן המדו' שנק' ז\"ת דע\"י כידוע דג\"ר דע\"י נבדל בערך כו' שהן מקיפי' למוחי' שבד' פ' מ\"מ בא בבחי' ידירה בהתלבשו' חיצונו' להיו' מקיף למוחי' שבד' פ' שהן מקור המדו' כידוע דקדש והי' חו\"ב מהן נסתעף חו\"ג דשמע והי' כו' משא\"כ בחי' הגויל דפרשיו' שהוא מקיף לאותיו' דפרשיות הרי הוא מקיף לבחי' הפנימי' ע\"כ הוא לבן ממש כדוגמת בחי' לובן העליון דחוורתי דרישא דע\"י כו' כנ\"ל וד\"ל (ועדיין אין כל זה מתיישב לנכון דלמה יהי' יתרון מעלה באותיו' דד' פרשיות שהמקיף שלהן יותר עליון ממקיף דמוחין שבהן כמו הבתים כו' וד\"ל):\n(מא) <b>_והנה</b> אחר כל הנ\"ל יש לבאר שרש ענין תש\"י ותש\"ר דהיינו תפלה מיושב מיוצר אור עד ש\"ע זהו בחי' תש\"י כידוע וש\"ע הוא בבחי' תש\"ר דנק' תפלה מעומד כמ\"ש בפע\"ח בהיות מבואר למעלה דשמאלו תחת כו' הוא ביוצר אור עד ש\"ע וימינו תחבקני הוא בש\"ע והעניו מבואר למעלה דבחי' הרצוא מלמטה למעלה בבחי' בליטה ממשיך מלמעלה בחי' שקיעה שהוא התלבשות אורות בכלים והיינו כחותם בגדול זרועך שהוא בחי' תפלה מיושב דיוצר אור שהוא רק בחי רצוא בהעלאת מ\"ן דאהבה כמו שמספרים איך שהמלאכים משבחים ואומרים קדוש כו' ועי\"ז נמשך בחי' מ\"ד אה\"ע אהבתנו מלמעלה למטה בחי' שקיעה עד שבק\"ש דנמשך אורות עליונים בכלים ממש הן רמ\"ח תיבין דמ\"ח ומחברין כו' שזהו כל עיקר בנין דהשתלשלות באורות וכלים דוקא דהיינו שהאור מתיישב ונעלם בתוך הכלי המלבישו כו' וזהו כמו בחי' תש\"י שנא' בהן לך לאות ולא לחרים לאות שצריכים להיות מכוסים ולא מגולים כידוע לפי שזהו מבחי' התלבשות האור בתוך כלים מכלים שונים כמ\"ש את האור כי טוב פי' טוב לגנוז האור בכלי כו' (וכמו מאדני הקרשים שהן בית קיבול כו' כך בחי' מל' שם אד' לקבל האור בכלי כו') וזהו הטעם ג\"כ שנק' תפלה מיושב דוקא שבחי' ישיבה הוא בבחי' ירידה והתלבשות שבא מלמטה כמו באשה קרא מושב שהוא בחי' המל' בחי' דנק' בחי' אותיות וכלים המגבילים כו' וכידוע בדברי רז\"ל דאין ישיבה אלא בבחי' המל' דווקא כמארז\"ל שאין ישיבה בעזרה אלא למלכי בית דוד וכו' וכה\"ג למעלה בבחי' המל' נא' ישיבה כמו וישב ה' מלך לעולם כו' וכך הוא ענין תפלה מיושב שהוא בבחי' המל' בחי' התלבשות אור בכלי דוקא כמו באשה קרא מושב כו' להיותו גורם בחי' השקיעה שהאור נעלם ולא מגולה שזהו כתש\"י שנא' לך לאות מכוסה דוקא כמ\"ש כבוד אלקים הסתר כו' וד\"ל אך הנה בחי' תש\"ר הוא בש\"ע שנק' תפלה מעומד דוקא ולא מיושב כו' כמו תש\"ר שהן מגולים בבחי' בליטה על הראש בגלוי ולא' בהעלם והענין הוא כידוע דש\"ע נק' צלותא בלחש כמ\"ש חנה וקולה לא ישמע והיינו מצד בחי' בטול היש בתכלית כך שהוא בהעדר הרגשה עצמו לגמרי כמו אין מלה בלשוני רק אדני שפתי תפתח כו' וזהו כמו הנגש לפני המלך דקרוב שנתבטל ממציאותו לגמרי ואין בו כח לדבר רק בחשאי מאד כו' לפי שבש\"ע הוא בבחינת גלוי עצמות אלקות תמן קאתי מלכא לכך קול דממה דקה לא ישמע בהרגש"],[1700400437,"כלל וכלל בתכלית בטול המציאות ולכך כל המשמיע קולו בש\"ע ה\"ז מקטני אמנה שנק' קטנות המוחים שבריחוק שמתפעל בהרגש ברעש ואש כו' כידוע וזהו ענין הכריעות בברוך שהוא בטול העצמות מכל וכל ולכך נק' תפלה מעומד דוקא כי כל עמידה הוא בחי' בטול בעצם כמו העומד לפני מי שגדול הימנו הרבה שבעמידה זו הורה על בחי' התפשטות ויש בפ\"ע דוקא היפך הבטול) דלכך אין ישיבה בעזרה רק למלכים שהמל' בבחי' יש כו') וכמו אשר עמדתי לפניו וכן ואברהם עודנו עומד כו' וכן במלאכים כתי' בעמדם תרפנה כו' בהעדר התפשטות בתנועות ידיו שיהא נראה כאבן דומם כמו רבא פכר ידי' ומצלי כידוע וכל זה מורה רק בטול הכלי הנק' שקיע' שהוא דרך כלל העדר ההתפשטות והיש משא\"כ הישיבה כו' ולכך בחי' ש\"ע הוא גורם ענין הבליטה שהוא גלוי האור בלא העלם בכלי כלל אדרבה גלוי עצם האור כמו שהוא דוקא כתש\"ר שהן מגולים דוקא כנ\"ל וזהו ענין וימינו תחבקני פי' ימינו הוא בחי' רב חסד העליון דפנימית ע\"י שמאיר כמו שהוא בלתי התעלמות והתלבשות בכלי שמתפשט למטה מטה ולא יחשך אורו כלל (כי אור החסד העצמי כמו שהוא בלא כלי אינו מתעבה גם ברבוי ההשתלשלות עד למטה מטה ביותר כמו וימינך פשוטה לקבל שבים הגם שהן בשאול תחתית מגיע לשם רב חסד העליון לקבלה וכמו גבי מנשה שחתר ברקיע כו') והתפשטות זאת מתפשטת למטה יותר מן התפשטות הרצועות שאינן נמשכין רק על הלב כו') וראיה ממ\"ש בתש\"ר וראו כל ע\"ה ויראו גם הם שהתש\"ר נק' שומר שהחיצונים בורחין ממנו כשרואין אותן ע\"ג הראש כו') וכל זה רק מצד בחי' ביטול היש בתכלית בש\"ע שמזה יבא האור העליון ממיל' כמו שהוא מבלי התלבשות בכלי דאתעדל\"ת עושה אתעדל\"ע כמוהו ומאחר שנתבטל היש מלמטה בא מלמעלה ג\"כ בלא כלי כו' ולכך נק' ש\"ע תפלה מעומד דוקא בלי ישיבה להתלבש בכלי ויש כלל (אך לכאורה יש סתירה לזה במה שאנו מוצאי' בח\"י ברכאן דש\"ע שהן ח\"י המשכות בכלים דוקא כמו רפאינו ברך עלינו שהן שאלת צרכים שבאי' בכלי ויש דוקא ונק' בגמ' חיי שעה כידוע בדברי רז\"ל וגם במדרש שמפני מה ישראל צועקין בתפלתן ואינן נענין שכשהן קוראין אין קוראין ומכוונין בשם והוא שמות מיוסדי' דכל ברכ' כמו רפאינו יש לכוין בשם הוי' בניקוד חולם בהשיבנו בשם הויה בניקוד צירי ובברך עלינו בהוי' בניקוד חירק כמ\"ש לעיל באריכות אך האמת הוא דיש הפרש בזה בין כשכורע בברוך לזוקף בשם דהכריעה בברוך הוא השתחווא' בטול היש בתכלית כנ\"ל ונעשה עי\"ז ח\"י המשכות עליונות בח\"י חוליות כידוע בענין הקב\"ה מתפלל כו' (וח\"י חוליות הוא עושה חבור ובנין בכללות הגוף וכמו שכתוב במ\"א"],[1700400438,"דלכך התפלה אינה נחשבת מרמ\"ח מצות עשה דתפלה דרבנן משום דשרשה בחוט שבמוח ההולך בח\"י חוליו' שהוא מעמד ומצב כל הרמ\"ח אברי' כו') וכשזוקף בשם ה\"ז בא בבחי' כלי דשם הוי' כמו שם הוי' בנקו' צירי או סגול כנ\"ל שבא בהשתלשלות שפע ממש כנ\"ל [ולמעלה מבוא ש\"ע הוא כמו ממוצע שנק' בחי' שקיעה לגבי בליטה דתש שהוא אור בלא כלי כלל ולפ\"ז בטול היש דש\"ע גורם המשכה בכלי) ואין זה מתיישב עדיין רק שבהכרח לומר דבש\"ע הוא מעין דלעתיד דכתיב ולא יכנף עוד כו' ולא כעכשיו דתפל' נק' חיי שעה וראי' ממי שתורתו אומנתו פטור מן התפלה שהתורה נק' חיי עולם ויש בכלל מאתים מנה ואע\"פ שגם אור התורה בא בבחי' כלים כסדר מועד נשים כו' מ\"מ לא בא לכלל המשכה גשמי' בחיי שעה דש\"ע לכך מי שתורתו כו' אבל המצות באים בכלי ממש וכמו התפלה ולע\"ל דכתיב לא יכנף עוד כו' שיהיה אור בלא כלי כלל לכאורה היינו למעלה מעלה מן בחי' הכלי' דמצות ובאמת עיקר העוה\"ב שעין בעין כו' בא מן המצו' דעכשיו כמ\"ש כ\"י יש להם חלק לעו\"הב שנא' ועמך כולם צדיקי' וצדיק אינו רק בקיום מצו' בפ\"מ ואפי' פושעי ישראל מלאי' מצות כו' כידוע הענין הוא דבאמת לע\"ל נא' א\"ח עט\"ב דהמצות שנק' מצות המלך וכן התפלה שהמה בבחי' מל' יתעלו למעלה מבחי' ז\"א בעלה כידוע דב\"ן יעלה למעלה בס\"ג שלמעל' ממ\"ה כו' ומ\"ש ולא יכנף כו' היינו דמצו' עצמ' יהיה שם הויה דבחילוף א\"ת ב\"ש נעשה מי\"ה מ\"צ כו' וכך התפלה לע\"ל למעלה מחיי עולם דתורה מטעם זה וכמ\"ש במ\"א ע\"פ אני בצדק אחזה פניך כו' ובזה מתורץ הקושיא הנ\"ל דאע\"ג דעכשיו התפלה נק' חיי שעה שרש' למעלה בבחי' עצם האור שלמעלה מן הכלי כו') ובזה יובן ג\"כ מ\"ש שימני כחותם בתש\"ר ???? לתש\"י היפך מ\"ש וקשרתם תחלה כנ\"ל דלע\"ל יוציא חמה מנרתקה הוא שיתגלה שם הוי' דז\"א בלי לבו' והסת' דשם אלקי' וכמ\"ש ולא יכנף עוד כו' משא\"כ עכשיו דשם אלקי' מסתי' על שם הוי' וכמ\"ש כי שמש ומגן ה' אלקי' כידוע והיינו תפילין דמארי עלמא דלע\"ל אחר הבירור דב\"ן שיעלה למעלה לעטרת ופאר דתש\"ר שנא' בהן ומי כעמך ישראל וכן ישראך אשר בך אתפאר בפאר דתש\"ר דווקא כי לכך תש\"ר קודם לתש\"י לע\"ל וז\"ש שימני עכשיו בגלות כמו לע\"ל שתש\"ר קודם כו' אבל עכשיו תש\"י דשם אלקים מלבוש לשם הויה הרי מלמטה למעלה בחי' המל' קודם והוא תש\"י דוקשרתם תחלה כו' וד\"ל (ולכאורה היה ראוי להיות להיפך דמאחר שמצד א\"ס עט\"ב נאמר אשר בך אתפאר כו' הרי צריך להניח תש\"י קודם לע\"ל דוקא ובאמת עיקר הטעם הוא לפני שלע\"ל יבוא האור מלמעלה למטה דתש\"ר קודם וכמבואר למעלה ואמנם זה יבא מצד בירור דב\"ן וכמ\"ש אשר בך דווקא אתפאר וד\"ל:\n"]]});
